                    <span className={`px-1.5 py-0.5 rounded-full text-[10px] ${r.isManual ? 'bg-blue-800 text-blue-200' : 'bg-slate-700 text-slate-300'}`}>
                      {r.isManual ? 'manual' : 'scheduled'}
