            >
                <div className="p-4 border-b flex items-center justify-between">
                    <h3 className="text-lg font-bold">編輯持倉</h3>
                    <button
                        onClick={onClose}
                        className="p-1 hover:bg-accent rounded-full transition-colors"
                    >
                        <X className="w-5 h-5" />
