function buildDecisionMeta(candidate: AutonomousResearchCandidate, snapshot: AutonomousResearchSnapshot) {
  return {
    marketState: snapshot.marketState,
    marketRegime: snapshot.marketRegime,
    marketRegimeConfidence: snapshot.marketRegimeConfidence,
    candidateScreenBucket: candidate.screenBucket,
    dataCoverage: snapshot.dataCoverage,
    reason: '純規則化決策，不修改 alpha/backtest/regime/scoring。',
  };
}

export async function buildStrategyProposals(
  snapshot: AutonomousResearchSnapshot,
): Promise<StrategyProposal[]> {
  const proposals: StrategyProposal[] = [];

  // Load learning feedback from past trade reviews + active optimization insights
  const [learning, activeInsights] = await Promise.all([
    loadLatestLearningInsight(),
    loadActiveInsights(),
  ]);

  const rankedCandidates = (() => {
    const tieredResult = runTieredGuardrail(activeInsights, {
      currentRegime: snapshot.marketState,
      callerLabel: 'DecisionLayer',
    });

    // Hard-gated setup types are excluded from candidate consideration
    const gatedSetupTypes = new Set(
      tieredResult.gatingDecisions
        .filter((g) => g.gatedSetupType !== undefined)
        .map((g) => g.gatedSetupType!),
    );
    const hasGlobalGate = tieredResult.gatingDecisions.some(
      (g) => g.gatedSetupType === undefined,
    );

    const eligible = hasGlobalGate
      ? []
      : gatedSetupTypes.size > 0
        ? snapshot.candidateStocks.filter((c) => !gatedSetupTypes.has(c.setupType))
        : snapshot.candidateStocks;

    // Diversity rescue: if all candidates are gated, exempt the most-common setup type
    const allSetupTypes = snapshot.candidateStocks.map((c) => c.setupType);
    const diversityResult = applyGateDiversityRule(tieredResult.gatingDecisions, allSetupTypes);
    const finalEligible =
      eligible.length === 0 && diversityResult.exemptedSetupType !== undefined
        ? snapshot.candidateStocks
            .filter((c) => c.setupType === diversityResult.exemptedSetupType)
        : eligible;

    return applyStrongInsightRankingPenalty(finalEligible, tieredResult.tiers).sort(
      (a, b) => b.alphaScore - a.alphaScore,
    );
  })();

  for (const candidate of rankedCandidates.slice(0, 5)) {
    const stock = await prisma.stock.findUnique({
      where: { id: candidate.symbol },
      select: { id: true, name: true, industry: true },
    });

    if (!stock) continue;

    const setupType = candidate.setupType;
    const conviction = candidate.conviction;
    const baseSizing = baseSizingForConviction(conviction);
    const { adjustedSizing, adjustmentNote } = applyLearningAdjustment(
      baseSizing,
      setupType,
      conviction,
      learning,
    );

    const meta = buildDecisionMeta(candidate, snapshot);

    const proposal: StrategyProposal = {
      snapshotId: snapshot.snapshotId,
      symbol: stock.id,
      setupType,
      thesis: candidate.thesis,
      entryCondition: buildEntryCondition(setupType),
      invalidationCondition: buildInvalidationCondition(setupType),
      stopLossRule: buildStopLossRule(setupType),
      takeProfitRule: buildTakeProfitRule(setupType),
      positionSizing: adjustedSizing,
      conviction,
      supportingSignals: candidate.supportingSignals,
      riskFactors: candidate.riskFactors,
      researchSnapshotId: snapshot.snapshotId ?? null,
      state: 'proposed',
      decisionMeta: {
        ...meta,
        learningFeedback: {
          hasLearningData: learning.hasLearningData,
          adjustmentNote,
          baseSizing,
          adjustedSizing,
          activeSuggestions: learning.activeSuggestions,
          insightRankingNote: candidate.insightPenaltyNote ?? null,
        },
      },
    };

    proposals.push(proposal);
  }

  return proposals;
}

/**
 * TriggerScoringEngine — Soft trigger scoring replaces hard boolean gating.
 *
 * Instead of shouldTriggerProposal() returning true/false,
 * scoreTriggerReadiness() returns a 0.0–1.0 score with component breakdown.
 *
 * Tiered entry based on score:
 *   < 0.3           → approved (no action)
 *   0.3 – 0.59      → shadow  (paper trade, tighter thresholds, review at ±3%)
 *   0.6 – 0.79      → pending (half-size trade, review at ±5%)
 *   ≥ 0.8           → triggered (full trade, existing behavior)
 *
 * Bootstrap mode: when system has 0 closed trades, thresholds shift down by 0.2.
 */

import type { AutonomousResearchSnapshot, StrategyProposal } from './types';
import {
  computeTriggerScoreInsightMultiplier,
  computeTieredScoreMultiplier,
  type OptimizationInsightRecord,
} from './InsightIntegrationLayer';
import { runTieredGuardrail } from './InsightGuardrailLayer';
import { shouldProbe, PROBE_SIZING_MULTIPLIER } from './GateRecoveryEngine';

// ─── Types ───────────────────────────────────────────────────────

export interface TriggerScoreComponent {
  name: string;
  score: number;
  maxScore: number;
  met: boolean;
  detail: string;
}

export interface TriggerScore {
  /** Final score after regime multiplier, 0.0–1.0 */
  finalScore: number;
  /** Raw sum of components before regime multiplier */
  rawScore: number;
  /** Regime multiplier applied */
  regimeMultiplier: number;
  /** Individual component breakdown */
  components: TriggerScoreComponent[];
  /** Derived trade mode */
  tradeMode: 'none' | 'shadow' | 'pending' | 'full';
  /** Whether bootstrap mode lowered thresholds */
  bootstrapActive: boolean;
  /** True when a critical-tier insight hard-gated this setup. */
  gated?: boolean;
  /** Human-readable gate reason when gated = true. */
  gatingReason?: string;
  /** True when this trade bypassed a gate as a shadow probe. */
  isProbe?: boolean;
  /** Audit tag identifying this probe attempt, e.g. 'probe:trend:AAPL:2024-01-15'. */
  probeTag?: string;
  /** Position sizing multiplier from insight tier analysis (0.5 when strong insights present). */
  insightSizingMultiplier?: number;
}

export interface QuoteRow {
  date: string;
  open: number;
  high: number;
  low: number;
  close: number;
  volume: number;
  change: number;
}

// ─── Thresholds ──────────────────────────────────────────────────

const NORMAL_THRESHOLDS = { shadow: 0.3, pending: 0.6, triggered: 0.8 };
const BOOTSTRAP_THRESHOLDS = { shadow: 0.1, pending: 0.4, triggered: 0.6 };

// ─── Helpers ─────────────────────────────────────────────────────

function average(values: number[]): number {
  return values.length === 0 ? 0 : values.reduce((s, v) => s + v, 0) / values.length;
}

function recentReturn(quotes: QuoteRow[], days: number): number {
  if (quotes.length <= days) return 0;
  const latest = quotes[quotes.length - 1].close;
  const prev = quotes[quotes.length - 1 - days].close;
  return prev === 0 ? 0 : (latest - prev) / prev;
}

function movingAverage(quotes: QuoteRow[], period: number): number | null {
  if (quotes.length < period) return null;
  return average(quotes.slice(-period).map((q) => q.close));
}

function averageVolume(quotes: QuoteRow[], period: number): number {
  if (quotes.length < period) return 0;
  return average(quotes.slice(-period).map((q) => q.volume));
}

// ─── Regime Multiplier ──────────────────────────────────────────

function regimeScoringMultiplier(marketState: AutonomousResearchSnapshot['marketState']): number {
  if (marketState === 'trending') return 1.0;
  if (marketState === 'recovery') return 0.9;
  if (marketState === '震盪') return 0.8;
  // defensive — softer than the old hard block (was 0.35 for risk; here 0.65 for trigger)
  return 0.65;
}

// ─── Setup-Specific Scoring ─────────────────────────────────────

function scoreTrend(
  quotes: QuoteRow[],
  snapshot: AutonomousResearchSnapshot,
): TriggerScoreComponent[] {
  const components: TriggerScoreComponent[] = [];
  const ma20 = movingAverage(quotes, 20);
  const latest = quotes[quotes.length - 1];
  const ret5 = recentReturn(quotes, 5);
  const ret10 = recentReturn(quotes, 10);
  const avgVol10 = averageVolume(quotes, 10);

  const aboveMa = ma20 != null && latest.close > ma20;
  components.push({
    name: 'price_above_ma20',
    score: aboveMa ? 0.3 : (ma20 != null && latest.close > ma20 * 0.97 ? 0.1 : 0),
    maxScore: 0.3,
    met: aboveMa,
    detail: `close=${latest.close.toFixed(1)} ma20=${ma20?.toFixed(1) ?? 'N/A'}`,
  });

  const ret5Positive = ret5 > 0;
  components.push({
    name: 'ret5_positive',
    score: ret5Positive ? 0.25 : (ret5 > -0.02 ? 0.08 : 0),
    maxScore: 0.25,
    met: ret5Positive,
    detail: `ret5=${(ret5 * 100).toFixed(2)}%`,
  });

  const notDefensive = snapshot.marketState !== 'defensive';
  components.push({
    name: 'market_not_defensive',
    score: notDefensive ? 0.25 : 0.05,
    maxScore: 0.25,
    met: notDefensive,
    detail: `marketState=${snapshot.marketState}`,
  });

  const volumeUp = latest.volume > avgVol10 * 1.05;
  components.push({
    name: 'volume_confirmation',
    score: volumeUp ? 0.1 : 0,
    maxScore: 0.1,
    met: volumeUp,
    detail: `vol=${latest.volume} avgVol10=${avgVol10.toFixed(0)}`,
  });

  const ret10Positive = ret10 > 0;
  components.push({
    name: 'ret10_positive',
    score: ret10Positive ? 0.1 : 0,
    maxScore: 0.1,
    met: ret10Positive,
    detail: `ret10=${(ret10 * 100).toFixed(2)}%`,
  });

  return components;
}

function scoreRebound(
  quotes: QuoteRow[],
  _snapshot: AutonomousResearchSnapshot,
): TriggerScoreComponent[] {
  const components: TriggerScoreComponent[] = [];
  const ma20 = movingAverage(quotes, 20);
  const latest = quotes[quotes.length - 1];
  const ret10 = recentReturn(quotes, 10);
  const low5 = Math.min(...quotes.slice(-5).map((q) => q.low));

  // Bounce from low — tiered scoring
  const aboveLowStrict = latest.close > low5 * 1.01;
  const aboveLowRelaxed = latest.close > low5 * 1.005;
  components.push({
    name: 'bounce_from_low',
    score: aboveLowStrict ? 0.3 : (aboveLowRelaxed ? 0.15 : 0),
    maxScore: 0.3,
    met: aboveLowStrict,
    detail: `close=${latest.close.toFixed(1)} low5=${low5.toFixed(1)} strict=${aboveLowStrict} relaxed=${aboveLowRelaxed}`,
  });

  // Not overextended above MA
  const belowMaCap = ma20 != null && latest.close < ma20 * 1.08;
  const belowMaWider = ma20 != null && latest.close < ma20 * 1.12;
  components.push({
    name: 'below_ma_cap',
    score: belowMaCap ? 0.25 : (belowMaWider ? 0.1 : 0),
    maxScore: 0.25,
    met: belowMaCap,
    detail: `close=${latest.close.toFixed(1)} ma20×1.08=${ma20 != null ? (ma20 * 1.08).toFixed(1) : 'N/A'}`,
  });

  // Recent drawdown not too deep
  const ret10Contained = ret10 < 0.05;
  const ret10Moderate = ret10 < 0.08;
  components.push({
    name: 'drawdown_contained',
    score: ret10Contained ? 0.25 : (ret10Moderate ? 0.1 : 0),
    maxScore: 0.25,
    met: ret10Contained,
    detail: `ret10=${(ret10 * 100).toFixed(2)}%`,
  });

  // Volume showing recovery interest
  const avgVol10 = averageVolume(quotes, 10);
  const volRecovery = latest.volume > avgVol10 * 0.8;
  components.push({
    name: 'volume_recovery',
    score: volRecovery ? 0.2 : 0,
    maxScore: 0.2,
    met: volRecovery,
    detail: `vol=${latest.volume} avgVol10=${avgVol10.toFixed(0)}`,
  });

  return components;
}

function scoreEvent(
  quotes: QuoteRow[],
  snapshot: AutonomousResearchSnapshot,
): TriggerScoreComponent[] {
  const components: TriggerScoreComponent[] = [];
  const ret5 = recentReturn(quotes, 5);

  const hasSignals = snapshot.riskSignals.length > 0;
  components.push({
    name: 'risk_signals_present',
    score: hasSignals ? 0.35 : 0,
    maxScore: 0.35,
    met: hasSignals,
    detail: `signalCount=${snapshot.riskSignals.length}`,
  });

  const notDefensive = snapshot.marketState !== 'defensive';
  components.push({
    name: 'market_not_defensive',
    score: notDefensive ? 0.25 : 0.05,
    maxScore: 0.25,
    met: notDefensive,
    detail: `marketState=${snapshot.marketState}`,
  });

  const notCrashing = ret5 > -0.05;
  components.push({
    name: 'not_deeply_negative',
    score: notCrashing ? 0.2 : 0,
    maxScore: 0.2,
    met: notCrashing,
    detail: `ret5=${(ret5 * 100).toFixed(2)}%`,
  });

  const goodCoverage = snapshot.dataCoverage === 'full' || snapshot.dataCoverage === 'limited';
  components.push({
    name: 'data_coverage',
    score: goodCoverage ? 0.2 : 0,
    maxScore: 0.2,
    met: goodCoverage,
    detail: `coverage=${snapshot.dataCoverage}`,
  });

  return components;
}

function scoreFundamental(
  quotes: QuoteRow[],
  snapshot: AutonomousResearchSnapshot,
  proposal: StrategyProposal,
): TriggerScoreComponent[] {
  const components: TriggerScoreComponent[] = [];
  const ma20 = movingAverage(quotes, 20);
  const latest = quotes[quotes.length - 1];
  const ret5 = recentReturn(quotes, 5);

  const ret5Positive = ret5 > 0;
  components.push({
    name: 'ret5_positive',
    score: ret5Positive ? 0.3 : (ret5 > -0.02 ? 0.1 : 0),
    maxScore: 0.3,
    met: ret5Positive,
    detail: `ret5=${(ret5 * 100).toFixed(2)}%`,
  });

  const aboveMa = ma20 != null && latest.close > ma20 * 0.95;
  components.push({
    name: 'price_near_ma20',
    score: aboveMa ? 0.3 : 0,
    maxScore: 0.3,
    met: aboveMa,
    detail: `close=${latest.close.toFixed(1)} ma20×0.95=${ma20 != null ? (ma20 * 0.95).toFixed(1) : 'N/A'}`,
  });

  const goodCoverage = snapshot.dataCoverage === 'full';
  components.push({
    name: 'data_coverage_full',
    score: goodCoverage ? 0.2 : (snapshot.dataCoverage === 'limited' ? 0.1 : 0),
    maxScore: 0.2,
    met: goodCoverage,
    detail: `coverage=${snapshot.dataCoverage}`,
  });

  const highConviction = proposal.conviction === 'high';
  components.push({
    name: 'high_conviction',
    score: highConviction ? 0.2 : (proposal.conviction === 'mid' ? 0.1 : 0),
    maxScore: 0.2,
    met: highConviction,
    detail: `conviction=${proposal.conviction}`,
  });

  return components;
}

// ─── Main Scoring Function ──────────────────────────────────────

export function scoreTriggerReadiness(
  proposal: StrategyProposal,
  quotes: QuoteRow[],
  snapshot: AutonomousResearchSnapshot,
  options?: { bootstrapMode?: boolean; insights?: OptimizationInsightRecord[] },
): TriggerScore {
  if (quotes.length < 20) {
    return {
      finalScore: 0,
      rawScore: 0,
      regimeMultiplier: 0,
      components: [],
      tradeMode: 'none',
      bootstrapActive: false,
    };
  }

  let components: TriggerScoreComponent[];
  switch (proposal.setupType) {
    case 'trend':
      components = scoreTrend(quotes, snapshot);
      break;
    case 'rebound':
      components = scoreRebound(quotes, snapshot);
      break;
    case 'event':
      components = scoreEvent(quotes, snapshot);
      break;
    case 'fundamental':
      components = scoreFundamental(quotes, snapshot, proposal);
      break;
    default:
      components = scoreFundamental(quotes, snapshot, proposal);
  }

  const rawScore = Math.min(1, components.reduce((sum, c) => sum + c.score, 0));
  const regimeMul = regimeScoringMultiplier(snapshot.marketState);
  const finalScore = Math.min(1, rawScore * regimeMul);

  const bootstrap = options?.bootstrapMode ?? false;
  const thresholds = bootstrap ? BOOTSTRAP_THRESHOLDS : NORMAL_THRESHOLDS;

  let tradeMode: TriggerScore['tradeMode'] = 'none';
  if (finalScore >= thresholds.triggered) {
    tradeMode = 'full';
  } else if (finalScore >= thresholds.pending) {
    tradeMode = 'pending';
  } else if (finalScore >= thresholds.shadow) {
    tradeMode = 'shadow';
  }

  // Run tiered guardrail: filters insights + classifies into soft/strong/critical
  const now = new Date();
  const tieredResult = runTieredGuardrail(options?.insights ?? [], {
    currentRegime: snapshot.marketState,
    symbol: proposal.symbol,
    setupType: proposal.setupType,
    callerLabel: 'TriggerScoring',
  });

  // Hard gate: critical-tier insight blocks this setup entirely
  const gate = tieredResult.gatingDecisions.find(
    (g) => g.gatedSetupType === undefined || g.gatedSetupType === proposal.setupType,
  );
  if (gate) {
    // Probe mode: deterministically allow a fraction of gated setups through as shadow probes
    const probeDecision = shouldProbe(
      gate,
      { symbol: proposal.symbol, dateStr: now.toISOString().slice(0, 10) },
      now,
    );
    if (probeDecision.allowed) {
      return {
        finalScore: Math.min(1, finalScore * PROBE_SIZING_MULTIPLIER),
        rawScore,
        regimeMultiplier: regimeMul,
        components: [
          ...components,
          {
            name: 'probe_bypass',
            score: finalScore * (PROBE_SIZING_MULTIPLIER - 1),
            maxScore: 0,
            met: true,
            detail: `[PROBE] ${probeDecision.reason} tag=${probeDecision.probeTag}`,
          },
        ],
        tradeMode: 'shadow',
        bootstrapActive: bootstrap,
        gated: false,
        isProbe: true,
        probeTag: probeDecision.probeTag,
        insightSizingMultiplier: PROBE_SIZING_MULTIPLIER,
      };
    }
    return {
      finalScore: 0,
      rawScore,
      regimeMultiplier: regimeMul,
      components: [
        ...components,
        {
          name: 'insight_gate',
          score: -finalScore,
          maxScore: 0,
          met: false,
          detail: gate.reason,
        },
      ],
      tradeMode: 'none',
      bootstrapActive: bootstrap,
      gated: true,
      gatingReason: gate.reason,
      insightSizingMultiplier: 0,
    };
  }

  const { multiplier, appliedInsights } = computeTieredScoreMultiplier(
    proposal.symbol,
    proposal.setupType,
    tieredResult.tiers,
  );

  const adjustedFinalScore = multiplier < 1.0 ? Math.min(1, finalScore * multiplier) : finalScore;
  const adjustedRawScore = multiplier < 1.0 ? Math.min(1, rawScore * multiplier) : rawScore;

  let adjustedTradeMode = tradeMode;
  if (multiplier < 1.0) {
    if (adjustedFinalScore >= thresholds.triggered) adjustedTradeMode = 'full';
    else if (adjustedFinalScore >= thresholds.pending) adjustedTradeMode = 'pending';
    else if (adjustedFinalScore >= thresholds.shadow) adjustedTradeMode = 'shadow';
    else adjustedTradeMode = 'none';
  }

  const tierSummary = [
    tieredResult.tiers.soft.length > 0 ? `soft=${tieredResult.tiers.soft.length}` : null,
    tieredResult.tiers.strong.length > 0 ? `strong=${tieredResult.tiers.strong.length}` : null,
    tieredResult.tiers.critical.length > 0 ? `critical=${tieredResult.tiers.critical.length}` : null,
  ].filter(Boolean).join(',');

  const adjustedComponents =
    multiplier < 1.0
      ? [
          ...components,
          {
            name: 'insight_adjustment',
            score: adjustedFinalScore - finalScore,
            maxScore: 0,
            met: false,
            detail:
              `Multiplier=${multiplier.toFixed(3)} ` +
              `cap=${tieredResult.strongPenaltyCap.toFixed(2)} ` +
              `guardrail(${tieredResult.log.passedCount}/${tieredResult.log.totalInsights} passed` +
              `${tierSummary ? `, tiers: ${tierSummary}` : ''}) ` +
              `[${appliedInsights.join(', ')}]`,
          },
        ]
      : components;

  return {
    finalScore: adjustedFinalScore,
    rawScore: adjustedRawScore,
    regimeMultiplier: regimeMul,
    components: adjustedComponents,
    tradeMode: adjustedTradeMode,
    bootstrapActive: bootstrap,
    gated: false,
    insightSizingMultiplier: tieredResult.positionSizingMultiplier,
  };
}

// ─── Shadow Trade Thresholds ────────────────────────────────────

export function shadowSetupThresholds(setupType: StrategyProposal['setupType']) {
  // Shadow trades: tighter thresholds for faster feedback
  if (setupType === 'trend') return { target: 0.06, stop: -0.045, maxHoldDays: 9, reviewThreshold: 3 };
  if (setupType === 'rebound') return { target: 0.045, stop: -0.038, maxHoldDays: 6, reviewThreshold: 3 };
  if (setupType === 'event') return { target: 0.075, stop: -0.053, maxHoldDays: 7, reviewThreshold: 3 };
  return { target: 0.06, stop: -0.045, maxHoldDays: 12, reviewThreshold: 3 };
}

// ─── Sizing Multiplier by Trade Mode ────────────────────────────

export function tradeModePositionMultiplier(tradeMode: TriggerScore['tradeMode']): number {
  if (tradeMode === 'full') return 1.0;
  if (tradeMode === 'pending') return 0.5;
  if (tradeMode === 'shadow') return 0.3;
  return 0;
}

/**
 * InsightGuardrailLayer — unit tests
 *
 * Tests cover:
 *   1.  computeDecayedConfidence — fresh insight (age≈0) → unchanged
 *   2.  computeDecayedConfidence — at 50% of TTL → confidence × 0.5
 *   3.  computeDecayedConfidence — no createdAt → raw confidence returned
 *   4.  validateInsightEvidence — zero confidence → invalid
 *   5.  validateInsightEvidence — insufficient evidence count → invalid
 *   6.  validateInsightEvidence — valid insight → passes
 *   7.  applyRegimePenalty — regime-independent type → no penalty
 *   8.  applyRegimePenalty — matching regime → no penalty
 *   9.  applyRegimePenalty — mismatching regime → confidence × 0.5
 *   10. applyRegimePenalty — no currentRegime context → always matches
 *   11. detectConflicts — data_quality_issue + indicator_insufficient → REDUNDANT
 *   12. detectConflicts — score_bias + setup_imbalance → CORRELATED
 *   13. detectConflicts — no conflict pairs → []
 *   14. resolveConflicts — REDUNDANT: drops lower-confidence insight
 *   15. resolveConflicts — CORRELATED: downgrades both by 30%
 *   16. computeEstimatedPenalty — sum capped at GUARDRAIL_GLOBAL_CAP
 *   17. runGuardrail — 5 insights, estimated penalty exceeds cap → globalCapReached
 *   18. runGuardrail — low confidence after decay → rejected
 *   19. runGuardrail — regime mismatch → regime penalty may reject insight
 *   20. runGuardrail — conflict resolution inside pipeline → redundant pair resolved
 *   21. runGuardrail — empty input → empty result
 *   22. runGuardrail — validation failure → rejected with reason
 */

import {
  computeDecayedConfidence,
  validateInsightEvidence,
  applyRegimePenalty,
  detectConflicts,
  resolveConflicts,
  computeEstimatedPenalty,
  runGuardrail,
  classifyTier,
  computeGatingDecisions,
  runTieredGuardrail,
  GUARDRAIL_MIN_CONFIDENCE,
  GUARDRAIL_GLOBAL_CAP,
  TIER_SOFT_MAX,
  TIER_STRONG_MAX,
  STRONG_PENALTY_CAP,
  STRONG_SIZING_MULTIPLIER,
  MAX_GATED_SETUP_TYPES,
  type FilteredInsight,
  type GuardrailContext,
} from '../InsightGuardrailLayer';
import type { OptimizationInsightRecord } from '../InsightIntegrationLayer';

// ─── Helpers ──────────────────────────────────────────────────────────────────

const FUTURE_ISO = new Date(Date.now() + 86400000 * 14).toISOString(); // +14 days

function makeInsight(overrides: Partial<OptimizationInsightRecord> = {}): OptimizationInsightRecord {
  return {
    insightType: 'score_bias',
    sourceTaskId: 'task1',
    evidence: ['Score range: 0.05', 'Sample size: 30'],
    confidence: 0.9,
    severity: 'high',
    affectedSetupTypes: [],
    affectedSymbols: [],
    expiresAt: FUTURE_ISO,
    ...overrides,
  };
}

function makeFilteredInsight(
  overrides: Partial<OptimizationInsightRecord> & { decayedConfidence?: number } = {},
): FilteredInsight {
  const { decayedConfidence = 0.9, ...rest } = overrides;
  return { ...makeInsight(rest), decayedConfidence };
}

// ─── 1–3: computeDecayedConfidence ───────────────────────────────────────────

describe('computeDecayedConfidence', () => {
  it('returns confidence unchanged for a fresh insight (age ≈ 0)', () => {
    const insight = makeInsight({
      confidence: 0.8,
      createdAt: new Date().toISOString(),
      expiresAt: new Date(Date.now() + 86400000 * 14).toISOString(),
    });
    const result = computeDecayedConfidence(insight);
    // Age fraction ≈ 0 → decayFactor ≈ 1.0
    expect(result).toBeCloseTo(0.8, 1);
    expect(result).toBeGreaterThan(0.78);
  });

  it('returns confidence × 0.5 when insight is at 50% of its TTL', () => {
    const ttlMs = 14 * 86400000;
    // Created ttlMs/2 ago, expires ttlMs/2 from now → ageRatio = 0.5
    const created = new Date(Date.now() - ttlMs / 2).toISOString();
    const expires = new Date(Date.now() + ttlMs / 2).toISOString();
    const insight = makeInsight({
      confidence: 1.0,
      createdAt: created,
      expiresAt: expires,
    });
    // ageRatio = 0.5 → decayFactor = 0.5^(0.5 × 2) = 0.5^1 = 0.5
    const result = computeDecayedConfidence(insight);
    expect(result).toBeCloseTo(0.5, 2);
  });

  it('returns raw confidence when createdAt is undefined (test fixture)', () => {
    const insight = makeInsight({ confidence: 0.75 });  // no createdAt
    expect(computeDecayedConfidence(insight)).toBe(0.75);
  });
});

// ─── 4–6: validateInsightEvidence ─────────────────────────────────────────────

describe('validateInsightEvidence', () => {
  it('rejects an insight with zero confidence', () => {
    const result = validateInsightEvidence(makeInsight({ confidence: 0 }));
    expect(result.valid).toBe(false);
    expect(result.reason).toContain('zero_confidence');
  });

  it('rejects a score_bias insight with only 1 evidence string (min=2)', () => {
    const result = validateInsightEvidence(makeInsight({
      insightType: 'score_bias',
      evidence: ['Score range: 0.05'],  // only 1, min=2 for score_bias
    }));
    expect(result.valid).toBe(false);
    expect(result.reason).toContain('insufficient_evidence');
  });

  it('accepts a data_quality_issue with 1 evidence string (min=1)', () => {
    const result = validateInsightEvidence(makeInsight({
      insightType: 'data_quality_issue',
      evidence: ['Stale quote age: 72h'],
      confidence: 0.8,
    }));
    expect(result.valid).toBe(true);
    expect(result.reason).toBeUndefined();
  });

  it('accepts a valid score_bias with 2 evidence strings', () => {
    const result = validateInsightEvidence(makeInsight({
      insightType: 'score_bias',
      evidence: ['Score range: 0.05', 'Sample size: 30'],
      confidence: 0.7,
    }));
    expect(result.valid).toBe(true);
  });
});

// ─── 7–10: applyRegimePenalty ─────────────────────────────────────────────────

describe('applyRegimePenalty', () => {
  it('does NOT penalize regime-independent types (data_quality_issue)', () => {
    const insight = makeInsight({ insightType: 'data_quality_issue', regimeContext: 'trending' });
    const { effectiveConf, regimeMatch } = applyRegimePenalty(insight, 0.9, 'defensive');
    expect(effectiveConf).toBe(0.9);
    expect(regimeMatch).toBe(true);
  });

  it('does NOT penalize when regime matches', () => {
    const insight = makeInsight({ insightType: 'score_bias', regimeContext: 'trending' });
    const { effectiveConf, regimeMatch } = applyRegimePenalty(insight, 0.8, 'trending');
    expect(effectiveConf).toBe(0.8);
    expect(regimeMatch).toBe(true);
  });

  it('applies 50% penalty when regime-sensitive type mismatches', () => {
    const insight = makeInsight({ insightType: 'sector_misalignment', regimeContext: 'trending' });
    const { effectiveConf, regimeMatch } = applyRegimePenalty(insight, 0.8, 'defensive');
    expect(effectiveConf).toBeCloseTo(0.4, 5);
    expect(regimeMatch).toBe(false);
  });

  it('always matches when no currentRegime is provided', () => {
    const insight = makeInsight({ insightType: 'score_bias', regimeContext: 'trending' });
    const { effectiveConf, regimeMatch } = applyRegimePenalty(insight, 0.8, undefined);
    expect(effectiveConf).toBe(0.8);
    expect(regimeMatch).toBe(true);
  });

  it('always matches when insight has no regimeContext tag', () => {
    const insight = makeInsight({ insightType: 'score_bias', regimeContext: undefined });
    const { effectiveConf, regimeMatch } = applyRegimePenalty(insight, 0.8, 'defensive');
    expect(effectiveConf).toBe(0.8);
    expect(regimeMatch).toBe(true);
  });
});

// ─── 11–13: detectConflicts ───────────────────────────────────────────────────

describe('detectConflicts', () => {
  it('detects REDUNDANT conflict: data_quality_issue + indicator_insufficient', () => {
    const insights: FilteredInsight[] = [
      makeFilteredInsight({ insightType: 'data_quality_issue' }),
      makeFilteredInsight({ insightType: 'indicator_insufficient', evidence: ['3 symbols below threshold'] }),
    ];
    const conflicts = detectConflicts(insights);
    expect(conflicts).toHaveLength(1);
    expect(conflicts[0].resolution).toBe('REDUNDANT');
    expect(conflicts[0].a).toBe('data_quality_issue');
    expect(conflicts[0].b).toBe('indicator_insufficient');
  });

  it('detects CORRELATED conflict: score_bias + setup_imbalance', () => {
    const insights: FilteredInsight[] = [
      makeFilteredInsight({ insightType: 'score_bias' }),
      makeFilteredInsight({ insightType: 'setup_imbalance', evidence: ['trend 95%', '20 trades'] }),
    ];
    const conflicts = detectConflicts(insights);
    expect(conflicts).toHaveLength(1);
    expect(conflicts[0].resolution).toBe('CORRELATED');
  });

  it('returns [] when no conflict pairs exist', () => {
    const insights: FilteredInsight[] = [
      makeFilteredInsight({ insightType: 'score_bias' }),
      makeFilteredInsight({ insightType: 'data_quality_issue', evidence: ['Stale quote age: 72h'] }),
    ];
    // score_bias + data_quality_issue is not a conflict pair
    const conflicts = detectConflicts(insights);
    expect(conflicts).toHaveLength(0);
  });
});

// ─── 14–15: resolveConflicts ──────────────────────────────────────────────────

describe('resolveConflicts', () => {
  it('REDUNDANT: drops the lower-confidence insight', () => {
    const highConf = makeFilteredInsight({ insightType: 'data_quality_issue', decayedConfidence: 0.9, evidence: ['e1'] });
    const lowConf = makeFilteredInsight({ insightType: 'indicator_insufficient', decayedConfidence: 0.65, evidence: ['e2'] });

    const conflicts = detectConflicts([highConf, lowConf]);
    const { resolved, removed } = resolveConflicts([highConf, lowConf], conflicts);

    expect(resolved).toHaveLength(1);
    expect(resolved[0].insightType).toBe('data_quality_issue');  // higher confidence kept
    expect(removed).toHaveLength(1);
    expect(removed[0].insightType).toBe('indicator_insufficient');
  });

  it('CORRELATED: downgrades both by 30% (each × 0.70)', () => {
    const scoreBias = makeFilteredInsight({ insightType: 'score_bias', decayedConfidence: 0.9 });
    const setupImb = makeFilteredInsight({ insightType: 'setup_imbalance', decayedConfidence: 0.8, evidence: ['trend 95%', '20 trades'] });

    const conflicts = detectConflicts([scoreBias, setupImb]);
    const { resolved, removed } = resolveConflicts([scoreBias, setupImb], conflicts);

    expect(resolved).toHaveLength(2);
    expect(removed).toHaveLength(0);

    const sb = resolved.find((i) => i.insightType === 'score_bias')!;
    const si = resolved.find((i) => i.insightType === 'setup_imbalance')!;
    expect(sb.decayedConfidence).toBeCloseTo(0.9 * 0.7, 5);
    expect(si.decayedConfidence).toBeCloseTo(0.8 * 0.7, 5);
    expect(sb.guardrailNote).toContain('conflict_downgrade');
  });
});

// ─── 16: computeEstimatedPenalty ─────────────────────────────────────────────

describe('computeEstimatedPenalty', () => {
  it('caps estimated penalty at GUARDRAIL_GLOBAL_CAP (0.25)', () => {
    const insights: FilteredInsight[] = [
      makeFilteredInsight({ insightType: 'data_quality_issue', decayedConfidence: 1.0, evidence: ['e'] }),
      makeFilteredInsight({ insightType: 'score_bias', decayedConfidence: 1.0 }),
      makeFilteredInsight({ insightType: 'time_exit_dominance', decayedConfidence: 1.0, evidence: ['60% time exits', '30 trades'] }),
      makeFilteredInsight({ insightType: 'sector_misalignment', decayedConfidence: 1.0, evidence: ['8/10 conflict', 'Conflict rate: 80%'] }),
    ];
    // raw: 0.15 + 0.10 + 0.05 + 0.07 = 0.37 → capped to 0.25
    const { estimatedRawPenalty, estimatedCappedPenalty, globalCapReached } =
      computeEstimatedPenalty(insights);

    expect(estimatedRawPenalty).toBeCloseTo(0.37, 2);
    expect(estimatedCappedPenalty).toBeCloseTo(GUARDRAIL_GLOBAL_CAP, 5);
    expect(globalCapReached).toBe(true);
  });

  it('returns cap-not-reached when total penalty is below cap', () => {
    const insights: FilteredInsight[] = [
      makeFilteredInsight({ insightType: 'score_bias', decayedConfidence: 0.7 }),
    ];
    // raw: 0.10 × 0.7 = 0.07 → not capped
    const { estimatedCappedPenalty, globalCapReached } = computeEstimatedPenalty(insights);
    expect(estimatedCappedPenalty).toBeCloseTo(0.07, 5);
    expect(globalCapReached).toBe(false);
  });
});

// ─── 17–22: runGuardrail integration ─────────────────────────────────────────

describe('runGuardrail', () => {
  it('returns empty filtered set when input is empty', () => {
    const result = runGuardrail([]);
    expect(result.filtered).toHaveLength(0);
    expect(result.rejected).toHaveLength(0);
    expect(result.conflicts).toHaveLength(0);
    expect(result.log.totalInsights).toBe(0);
    expect(result.log.passedCount).toBe(0);
  });

  it('rejects an insight that fails evidence validation', () => {
    const insight = makeInsight({
      insightType: 'score_bias',
      evidence: [],  // empty — fails min=2 for score_bias
      confidence: 0.9,
    });
    const result = runGuardrail([insight]);
    expect(result.filtered).toHaveLength(0);
    expect(result.rejected).toHaveLength(1);
    expect(result.rejected[0].reason).toContain('validation_failed');
  });

  it('rejects an insight whose decayed confidence drops below MIN_CONFIDENCE', () => {
    // Artificially create a very old insight (90% of TTL elapsed)
    const ttlMs = 14 * 86400000;
    const ageMs = ttlMs * 0.9;
    const created = new Date(Date.now() - ageMs).toISOString();
    const expires = new Date(Date.now() + ttlMs * 0.1).toISOString();
    const insight = makeInsight({
      confidence: 0.65,   // borderline — after decay at 90% TTL, well below 0.6
      createdAt: created,
      expiresAt: expires,
    });
    // decayFactor = 0.5^(0.9 × 2) = 0.5^1.8 ≈ 0.287 → effectiveConf = 0.65 × 0.287 ≈ 0.187 < 0.6
    const result = runGuardrail([insight]);
    expect(result.filtered).toHaveLength(0);
    expect(result.rejected).toHaveLength(1);
    expect(result.rejected[0].reason).toContain('low_decayed_confidence');
  });

  it('rejects a regime-sensitive insight when regime mismatches and result < MIN_CONFIDENCE', () => {
    // sector_misalignment is regime-sensitive; mismatch → ×0.5 penalty
    const insight = makeInsight({
      insightType: 'sector_misalignment',
      evidence: ['8/10 conflict', 'Rate: 80%'],
      confidence: 0.7,
      regimeContext: 'trending',
    });
    const context: GuardrailContext = { currentRegime: 'defensive', callerLabel: 'Test' };
    // effectiveConf = 0.7 × 0.5 = 0.35 < 0.6 → rejected
    const result = runGuardrail([insight], context);
    expect(result.filtered).toHaveLength(0);
    expect(result.rejected).toHaveLength(1);
    expect(result.rejected[0].reason).toContain('regime_mismatch');
    expect(result.log.perInsight[0].regimeMatch).toBe(false);
  });

  it('passes a regime-sensitive insight when regime matches', () => {
    const insight = makeInsight({
      insightType: 'score_bias',
      evidence: ['Score range: 0.05', 'Sample size: 30'],
      confidence: 0.8,
      regimeContext: 'trending',
    });
    const result = runGuardrail([insight], { currentRegime: 'trending' });
    expect(result.filtered).toHaveLength(1);
    expect(result.filtered[0].decayedConfidence).toBe(0.8);  // no createdAt → no decay
  });

  it('resolves REDUNDANT conflict pair in the pipeline (data_quality + indicator_insufficient)', () => {
    const dqInsight = makeInsight({
      insightType: 'data_quality_issue',
      evidence: ['Stale quote age: 72h'],
      confidence: 0.9,
    });
    const iiInsight = makeInsight({
      insightType: 'indicator_insufficient',
      evidence: ['3 symbols below threshold'],
      confidence: 0.7,
    });
    const result = runGuardrail([dqInsight, iiInsight]);

    // Both pass individual checks (no decay, no regime issue)
    // Conflict: REDUNDANT → drop indicator_insufficient (lower confidence)
    expect(result.filtered).toHaveLength(1);
    expect(result.filtered[0].insightType).toBe('data_quality_issue');
    expect(result.conflicts).toHaveLength(1);
    expect(result.conflicts[0].resolution).toBe('REDUNDANT');
    expect(result.log.conflictPairsFound).toBe(1);
    expect(result.log.rejectedCount).toBe(1);  // conflict-removed counts as rejected
  });

  it('sets globalCapReached=true when too many high-confidence insights exceed 25% cap', () => {
    const insights = [
      makeInsight({ insightType: 'data_quality_issue', confidence: 1.0, evidence: ['e1'] }),
      makeInsight({ insightType: 'score_bias', confidence: 1.0 }),
      makeInsight({ insightType: 'time_exit_dominance', confidence: 1.0, evidence: ['60% exits', '20 trades'] }),
      makeInsight({ insightType: 'sector_misalignment', confidence: 1.0, evidence: ['8/10', 'Rate: 80%'] }),
    ];
    const result = runGuardrail(insights);
    // No conflict between these 4 types (only score_bias+setup_imbalance and sector+time are pairs)
    // sector_misalignment + time_exit_dominance → CORRELATED → both ×0.7
    // raw: 0.15 + 0.10 + 0.05×0.7 + 0.07×0.7 = 0.15 + 0.10 + 0.035 + 0.049 = 0.334 > 0.25
    expect(result.log.globalCapReached).toBe(true);
    expect(result.log.estimatedCappedPenalty).toBeCloseTo(GUARDRAIL_GLOBAL_CAP, 5);
    expect(result.log.estimatedFinalMultiplier).toBeCloseTo(0.75, 5);
  });

  it('includes full audit log with timestamp, perInsight entries, and callerLabel', () => {
    const insight = makeInsight({ confidence: 0.85 });
    const result = runGuardrail([insight], { callerLabel: 'TestCaller', symbol: 'AAPL' });

    expect(result.log.callerLabel).toBe('TestCaller');
    expect(result.log.symbol).toBe('AAPL');
    expect(result.log.timestamp).toBeTruthy();
    expect(new Date(result.log.timestamp).getFullYear()).toBeGreaterThan(2020);
    expect(result.log.perInsight).toHaveLength(1);
    expect(result.log.perInsight[0].insightType).toBe('score_bias');
    expect(result.log.perInsight[0].originalConfidence).toBe(0.85);
    expect(result.log.perInsight[0].passed).toBe(true);
  });
});

