  it('classifies strong (NOT critical) when conf is exactly TIER_STRONG_MAX (0.9)', () => {
    const ins = makeFilteredInsight({
      insightType: 'sector_misalignment',
      decayedConfidence: TIER_STRONG_MAX,
      evidence: ['8/10 conflict', 'Rate: 80%'],
