  it('promotes shadow → pending when setup has winning track record', async () => {
    // Not in bootstrap (has closed trades)
    mockTradeCount
      .mockResolvedValueOnce(5)   // closedTradeCount → not bootstrap
      .mockResolvedValueOnce(0);  // bootstrapCap

