function makeOpenTrade(overrides: Record<string, unknown> = {}) {
  const yesterday = new Date();
  yesterday.setDate(yesterday.getDate() - 1);
  const entryDate = yesterday.toISOString().slice(0, 10);
  return {
    id: 99,
    symbol: '2330',
    setupType: 'trend',
    entryDate,
    entryPrice: 100,
    simulatedFillPrice: 100.15,
    quantity: 100,
    status: 'open',
    tradeMode: 'full',
    snapshotId: 1,
    marketContext: JSON.stringify({ marketState: 'trending', tradeMode: 'full' }),
    ...overrides,
  };
}

function makeCurrentQuotes(close: number, entryDate: string) {
  // 25 historical quotes leading up to entry, then one more today at the given close
  const base = Array.from({ length: 25 }, (_, i) => {
    const d = new Date(entryDate);
    d.setDate(d.getDate() - (25 - i));
    return {
      date: d.toISOString().slice(0, 10),
      open: 100, high: 102, low: 98, close: 100, volume: 10000, change: 0,
    };
  });
  // Add entry-date quote at the current close price
  base.push({ date: entryDate, open: close, high: close + 1, low: close - 1, close, volume: 10000, change: 0 });
  return base;
}

describe('closeOpenTrades', () => {
  beforeEach(() => {
    jest.clearAllMocks();
    mockTradeFindMany.mockResolvedValue([]);
    mockTradeUpdate.mockResolvedValue({});
    mockJournalUpdateMany.mockResolvedValue({ count: 1 });
    mockReviewCreate.mockResolvedValue({});
    mockReviewFindUnique.mockResolvedValue(null);
    mockSnapshotFindUnique.mockResolvedValue({
      id: 1,
      snapshotDate: '2026-04-16',
      marketState: 'trending',
      sectorStrength: '[]',
      candidateStocks: '[]',
      riskSignals: '[]',
      topInsights: '[]',
      dataCoverage: 'limited',
      limitations: '[]',
    });
  });

  it('returns zero counts when no open trades exist', async () => {
    mockTradeFindMany.mockResolvedValue([]);

    const result = await closeOpenTrades();

    expect(result.evaluated).toBe(0);
    expect(result.closed).toBe(0);
    expect(result.reviewsGenerated).toBe(0);
    expect(mockTradeUpdate).not.toHaveBeenCalled();
  });

  it('closes a full trade that hits the stop loss (-6%)', async () => {
    const trade = makeOpenTrade();
    mockTradeFindMany.mockResolvedValue([trade]);
    // price dropped to 94 → pnl = (94 - 100.15) / 100.15 ≈ -6.14%  (stop ≤ -6%)
    mockQuoteFindMany.mockResolvedValue(makeCurrentQuotes(94, trade.entryDate as string));

    const result = await closeOpenTrades();

    expect(result.closed).toBe(1);
    const updateCall = mockTradeUpdate.mock.calls[0][0];
    expect(updateCall.data.status).toBe('closed');
    expect(updateCall.data.exitReason).toBe('stop');
    expect(updateCall.data.stopHit).toBe(true);
  });

  it('closes a full trade that hits the target (+8%)', async () => {
    const trade = makeOpenTrade();
    mockTradeFindMany.mockResolvedValue([trade]);
    // price at 109 → pnl = (109 - 100.15) / 100.15 ≈ +8.83%
    mockQuoteFindMany.mockResolvedValue(makeCurrentQuotes(109, trade.entryDate as string));

    const result = await closeOpenTrades();

    expect(result.closed).toBe(1);
    const updateCall = mockTradeUpdate.mock.calls[0][0];
    expect(updateCall.data.status).toBe('closed');
    expect(updateCall.data.exitReason).toBe('target');
    expect(updateCall.data.targetHit).toBe(true);
  });

  it('closes a full trend trade on time exit (holdingDays >= 15) and ALWAYS generates a review', async () => {
    // entryDate 16 days ago → holdingDays = 16 >= maxHoldDays=15 for 'trend'
    const old = new Date();
    old.setDate(old.getDate() - 16);
    const entryDate = old.toISOString().slice(0, 10);
    const trade = makeOpenTrade({ entryDate, setupType: 'trend' });
    mockTradeFindMany.mockResolvedValue([trade]);

    // Quotes span from entry to yesterday so freshness guard passes (latest = yesterday)
    // Price stays flat — pnlPct ≈0% (well below 5% threshold, but time-exit always reviews)
    const quotes = Array.from({ length: 20 }, (_, i) => {
      const d = new Date(old);
      d.setDate(d.getDate() + i);
      return { date: d.toISOString().slice(0, 10), open: 100, high: 101, low: 99, close: 100.15, volume: 10000, change: 0 };
    });
    mockQuoteFindMany.mockResolvedValue(quotes);

    const result = await closeOpenTrades();

    expect(result.closed).toBe(1);
    const updateCall = mockTradeUpdate.mock.calls[0][0];
    expect(updateCall.data.status).toBe('closed');
    expect(updateCall.data.exitReason).toBe('time');
    // Time-exit ALWAYS generates a review regardless of pnlPct magnitude
    expect(result.reviewsGenerated).toBe(1);
    expect(mockReviewCreate).toHaveBeenCalledTimes(1);
  });

  it('updates P&L without closing when no exit condition is met', async () => {
    const trade = makeOpenTrade();
    mockTradeFindMany.mockResolvedValue([trade]);
    // price slightly up — well within stop/target bands
    mockQuoteFindMany.mockResolvedValue(makeCurrentQuotes(101.5, trade.entryDate as string));

    const result = await closeOpenTrades();

    expect(result.closed).toBe(0);
    const updateCall = mockTradeUpdate.mock.calls[0][0];
    expect(updateCall.data.status).toBe('open');
    expect(updateCall.data.exitReason).toBeUndefined();
    expect(updateCall.data.pnlPct).toBeDefined();
    expect(updateCall.data.holdingDays).toBeDefined();
  });

  it('generates a review when a closed trade has |pnlPct| >= 5%', async () => {
    const trade = makeOpenTrade();
    mockTradeFindMany.mockResolvedValue([trade]);
    // -6.14% stop hit → review should be generated
    mockQuoteFindMany.mockResolvedValue(makeCurrentQuotes(94, trade.entryDate as string));

    const result = await closeOpenTrades();

    expect(result.reviewsGenerated).toBe(1);
    expect(mockReviewCreate).toHaveBeenCalledTimes(1);
    const reviewCall = mockReviewCreate.mock.calls[0][0].data;
    expect(reviewCall.tradeId).toBe(trade.id);
    expect(reviewCall.triggerType).toBe('-5');
  });

  it('does NOT create a duplicate review if one already exists', async () => {
    const trade = makeOpenTrade();
    mockTradeFindMany.mockResolvedValue([trade]);
    mockQuoteFindMany.mockResolvedValue(makeCurrentQuotes(94, trade.entryDate as string));
    mockReviewFindUnique.mockResolvedValue({ tradeId: trade.id }); // review already exists

    const result = await closeOpenTrades();

    expect(result.reviewsGenerated).toBe(0);
    expect(mockReviewCreate).not.toHaveBeenCalled();
  });

  it('closes a shadow-open trade with shadow-closed status', async () => {
    const trade = makeOpenTrade({ status: 'shadow-open', tradeMode: 'shadow' });
    mockTradeFindMany.mockResolvedValue([trade]);
    mockQuoteFindMany.mockResolvedValue(makeCurrentQuotes(94, trade.entryDate as string));

    await closeOpenTrades();

    const updateCall = mockTradeUpdate.mock.calls[0][0];
    expect(updateCall.data.status).toBe('shadow-closed');
  });

  it('skips trades with no quotes', async () => {
    const trade = makeOpenTrade();
    mockTradeFindMany.mockResolvedValue([trade]);
    mockQuoteFindMany.mockResolvedValue([]);

    const result = await closeOpenTrades();

    expect(result.evaluated).toBe(1);
    expect(result.closed).toBe(0);
    expect(mockTradeUpdate).not.toHaveBeenCalled();
  });

  it('skips trades whose latest quote is stale (> 5 days old)', async () => {
    const trade = makeOpenTrade();
    mockTradeFindMany.mockResolvedValue([trade]);
    // latest quote date is 10 days ago
    const staleDate = new Date();
    staleDate.setDate(staleDate.getDate() - 10);
    const staleDateStr = staleDate.toISOString().slice(0, 10);
    mockQuoteFindMany.mockResolvedValue([
      { date: staleDateStr, open: 100, high: 102, low: 98, close: 100, volume: 10000, change: 0 },
    ]);

    const result = await closeOpenTrades();

    expect(result.closed).toBe(0);
    expect(mockTradeUpdate).not.toHaveBeenCalled();
  });
});

/**
 * AntiDeceptionValidator - 防自欺驗證模組
 *
 * 在顯示回測結果前，自動檢查是否存在以下問題：
 * 1. 結果過於完美 (可能過度擬合)
 * 2. 樣本不足
 * 3. 缺少交易成本
 * 4. 缺少 benchmark 對照
 * 5. 只展示最佳期間/參數
 * 6. Sharpe > 3 (幾乎不可能在真實市場達到)
 */

import type { PerformanceMetrics, BacktestResult } from './StrategyBacktestEngine';

export interface ValidationWarning {
  level: 'critical' | 'warning' | 'info';
  code: string;
  message: string;
  detail: string;
}

export interface ValidationReport {
  passed: boolean;
  trustScore: number;  // 0-100, higher = more trustworthy
  warnings: ValidationWarning[];
  summary: string;
}

export function validateBacktestResult(result: BacktestResult): ValidationReport {
  const warnings: ValidationWarning[] = [];
  let trustScore = 100;

  const m = result.metrics;

  // === CRITICAL: Suspiciously good results ===

  if (m.sharpeRatio > 3) {
    warnings.push({
      level: 'critical',
      code: 'SUSPICIOUS_SHARPE',
      message: `Sharpe Ratio ${m.sharpeRatio.toFixed(2)} 異常偏高`,
      detail: '真實市場中，年化 Sharpe > 2 已屬頂尖，> 3 幾乎不可能。此結果高度疑似過度擬合、生存者偏差、或遺漏交易成本。',
    });
    trustScore -= 30;
  }

  if (m.winRate > 0.8 && m.totalTrades > 10) {
    warnings.push({
      level: 'critical',
      code: 'SUSPICIOUS_WIN_RATE',
      message: `勝率 ${(m.winRate * 100).toFixed(1)}% 異常偏高`,
      detail: '80%+ 勝率在頻繁交易中極為罕見。可能存在前視偏差或過度擬合。',
    });
    trustScore -= 25;
  }

  if (m.maxDrawdown < 0.02 && m.totalTrades > 20 && m.totalReturn > 0.2) {
    warnings.push({
      level: 'critical',
      code: 'SUSPICIOUS_LOW_DD',
      message: `最大回撤僅 ${(m.maxDrawdown * 100).toFixed(2)}%，報酬卻達 ${(m.totalReturn * 100).toFixed(1)}%`,
      detail: '高報酬低回撤組合在真實市場中極為罕見。可能存在資料問題或前視偏差。',
    });
    trustScore -= 25;
  }

  if (m.cagr > 1.0) {
    warnings.push({
      level: 'critical',
      code: 'UNREALISTIC_CAGR',
      message: `年化報酬率 ${(m.cagr * 100).toFixed(1)}% 超過 100%`,
      detail: '持續年化報酬超過 100% 在現實中幾乎不可能維持。此結果可能來自極短期間或極端市場條件。',
    });
    trustScore -= 20;
  }

  // === WARNING: Sample insufficiency ===

  if (m.totalTrades < 10) {
    warnings.push({
      level: 'warning',
      code: 'INSUFFICIENT_TRADES',
      message: `僅 ${m.totalTrades} 筆交易，樣本嚴重不足`,
      detail: '統計上至少需要 30 筆以上交易才能評估策略是否具備統計顯著性。目前結果不可作為策略有效性的依據。',
    });
    trustScore -= 20;
  } else if (m.totalTrades < 30) {
    warnings.push({
      level: 'warning',
      code: 'LOW_TRADE_COUNT',
      message: `${m.totalTrades} 筆交易，樣本量偏低`,
      detail: '建議至少 30 筆交易以上再評估策略。目前結果僅供參考。',
    });
    trustScore -= 10;
  }

  if (m.samplePeriodDays < 126) {  // ~6 months
    warnings.push({
      level: 'warning',
      code: 'SHORT_PERIOD',
      message: `回測期間僅 ${m.samplePeriodDays} 天 (不足 6 個月)`,
      detail: '短期回測無法反映不同市場環境。建議至少回測 1-2 年以涵蓋多種市況。',
    });
    trustScore -= 15;
  } else if (m.samplePeriodDays < 252) {
    warnings.push({
      level: 'info',
      code: 'MODERATE_PERIOD',
      message: `回測期間 ${m.samplePeriodDays} 天 (不足 1 年)`,
      detail: '建議延長回測期間以涵蓋完整年度市場循環。',
    });
    trustScore -= 5;
  }

  // === WARNING: Cost issues ===

  if (m.costDrag < 0.001 && m.totalTrades > 5) {
    warnings.push({
      level: 'warning',
      code: 'NO_COST_DETECTED',
      message: '交易成本影響極低，可能遺漏',
      detail: '台股每筆來回交易成本約 0.585%。若未計入，回測報酬將被高估。',
    });
    trustScore -= 15;
  }

  // === INFO: Good practices ===

  if (m.exposure < 0.1 && m.totalReturn > 0.1) {
    warnings.push({
      level: 'info',
      code: 'LOW_EXPOSURE',
      message: `市場曝險時間僅 ${(m.exposure * 100).toFixed(1)}%`,
      detail: '大部分時間未持有部位。雖然降低風險，但也可能代表策略機會稀少。',
    });
  }

  if (m.maxConsecutiveLosses >= 5) {
    warnings.push({
      level: 'info',
      code: 'CONSECUTIVE_LOSSES',
      message: `最大連續虧損 ${m.maxConsecutiveLosses} 筆`,
      detail: '連續虧損 5 筆以上在心理與資金管理上具有挑戰性。實際操作時需有應對計畫。',
    });
  }

  // === Summary ===

  trustScore = Math.max(0, Math.min(100, trustScore));

  const criticalCount = warnings.filter(w => w.level === 'critical').length;
  const warningCount = warnings.filter(w => w.level === 'warning').length;

  let summary: string;
  if (criticalCount > 0) {
    summary = `⚠️ 發現 ${criticalCount} 個嚴重問題。回測結果不可信，需修正後重新驗證。`;
  } else if (warningCount > 0) {
    summary = `⚡ 發現 ${warningCount} 個注意事項。結果可參考但需謹慎解讀。`;
  } else {
    summary = '✅ 回測結果通過基本品質檢查。仍建議搭配 walk-forward 驗證及 benchmark 對照。';
  }

  return {
    passed: criticalCount === 0,
    trustScore,
    warnings,
    summary,
  };
}

/**
 * Format a validation report for display
 */
export function formatValidationReport(report: ValidationReport): string {
  const lines: string[] = [
    `═══ 回測品質驗證報告 ═══`,
    `信任分數: ${report.trustScore}/100`,
    `結論: ${report.summary}`,
    '',
  ];

  if (report.warnings.length > 0) {
    lines.push('詳細項目:');
    for (const w of report.warnings) {
      const icon = w.level === 'critical' ? '🚨' : w.level === 'warning' ? '⚠️' : 'ℹ️';
      lines.push(`${icon} [${w.code}] ${w.message}`);
      lines.push(`   ${w.detail}`);
    }
  }

  return lines.join('\n');
}

/**
 * AssetDoublingStrategyAdapter - 將 AssetDoubling 策略適配到標準回測引擎
 *
 * 原策略: AssetDoublingStrategy.ts
 * 此檔案: 將其規則轉譯為 StrategyDefinition interface
 *
 * 規則摘要:
 * - Entry: Price > MA10 > MA60, RSI < 80, ATR/Price ≤ 5%, 技術分數 ≥ 75
 * - Exit: Price < MA20 或 Price < RecentHigh - 2×ATR
 * - Stop: max(MA20, Recent20High - 2×ATR)
 * - Position: Half-Kelly with regime scaling
 */

import type { StrategyDefinition, BarContext, Position } from './StrategyBacktestEngine';

export const AssetDoublingAdapter: StrategyDefinition = {
  name: 'Asset Doubling Strategy',
  version: '2.0-validated',
  description: '資產翻倍策略 - 基於 MA/ATR/RSI 的趨勢跟隨策略，附完整交易成本與風控',

  shouldEnter: (ctx: BarContext): boolean => {
    const { indicators, close, volume } = ctx;
    const ma10 = indicators.ma10;
    const ma60 = indicators.ma60;
    const rsi = indicators.rsi;
    const atr = indicators.atr;
    const volumeRatio = indicators.volumeRatio ?? 0;

    // Need sufficient history
    if (ma10 === 0 || ma60 === 0) return false;

    // Core trend condition: Price > MA10 > MA60
    if (close <= ma10 || ma10 <= ma60) return false;

    // RSI not overbought (< 80)
    if (rsi >= 80) return false;

    // ATR filter: volatility not too high (≤ 5% of price)
    if (atr > 0 && (atr / close) > 0.05) return false;

    // Volume confirmation: at least average volume
    if (volumeRatio > 0 && volumeRatio < 0.8) return false;

    // Simplified technical score check
    // MA alignment strength
    const maStrength = (close - ma60) / ma60;
    if (maStrength < 0.02) return false; // need at least 2% above MA60

    // RSI in favorable zone (40-75)
    if (rsi < 40 || rsi > 75) return false;

    return true;
  },

  shouldExit: (ctx: BarContext, position: Position): boolean => {
    const { indicators, close } = ctx;
    const ma20 = indicators.ma20;

    // Exit if price drops below MA20
    if (ma20 > 0 && close < ma20) return true;

    // Exit if RSI extremely overbought
    if (indicators.rsi > 85) return true;

    return false;
  },

  calculateStopLoss: (ctx: BarContext): number => {
    const { indicators, close, history } = ctx;
    const atr = indicators.atr;
    const ma20 = indicators.ma20;

    // Recent 20-bar high
    const recent20 = history.slice(-20);
    const recentHigh = Math.max(...recent20.map(b => b.high));

    // Stop = max(MA20, RecentHigh - 2×ATR)
    const atrStop = atr > 0 ? recentHigh - 2 * atr : close * 0.93;
    const maStop = ma20 > 0 ? ma20 : close * 0.93;

    return Math.max(atrStop, maStop);
  },

  positionSizeFraction: (ctx: BarContext, capital: number): number => {
    const { indicators } = ctx;
    const atr = indicators.atr;
    const close = ctx.close;

    // Risk-based sizing: risk 2% of capital per trade
    const riskPct = 0.02;
    const stopDistance = atr > 0 ? 2 * atr : close * 0.07;
    const riskPerShare = stopDistance;

    if (riskPerShare <= 0 || close <= 0) return 0.1;

    // Position = (Capital × RiskPct) / RiskPerShare / Price
    const shares = (capital * riskPct) / riskPerShare;
    const positionValue = shares * close;
    const fraction = positionValue / capital;

    // Clamp to 5-25% of capital
    return Math.max(0.05, Math.min(0.25, fraction));
  },
};

/**
 * Simple MA Crossover for benchmark comparison
 */
export const SimpleMABenchmark: StrategyDefinition = {
  name: 'Simple MA10/60 Crossover',
  version: '1.0',
  description: 'MA10/60 交叉策略 - 作為 benchmark 使用',

  shouldEnter: (ctx) => {
    const ma10 = ctx.indicators.ma10;
    const ma60 = ctx.indicators.ma60;
