const VALID_DATE = '2026-05-07';
const VALID_DATE_DB = '20260507';
const FUTURE_DATE = '2026-12-31';
const PAST_DATE = '2024-01-15';
const INVALID_DATE = 'not-a-date';
const INVALID_DATE_2 = '2026-13-01'; // invalid month

