  // ── buildAsOfWhereClause contract ───────────────────────────

  describe('buildAsOfWhereClause() produces correct DB where clause', () => {
    it('B1: produces prismaWhere.date.lte in YYYYMMDD format', () => {
      const clause = buildAsOfWhereClause('StockQuote', VALID_DATE);
      expect(clause.prismaWhere).toEqual({ date: { lte: VALID_DATE_DB } });
    });

    it('B2: converts YYYY-MM-DD to YYYYMMDD correctly', () => {
      const clause = buildAsOfWhereClause('StockQuote', '2024-01-15');
      expect(clause.prismaWhere.date.lte).toBe('20240115');
    });

    it('B3: prismaWhere enforces <= asOfDate (not <)', () => {
      const clause = buildAsOfWhereClause('StockQuote', VALID_DATE);
      expect(clause.prismaWhere.date).toHaveProperty('lte');
      expect(clause.prismaWhere.date).not.toHaveProperty('lt');
    });

    it('B4: no gte in prismaWhere (only upper bound)', () => {
      const clause = buildAsOfWhereClause('MarketIndex', VALID_DATE);
      expect(clause.prismaWhere.date).not.toHaveProperty('gte');
    });

    it('B5: future date produces future lte (gate allows explicit future asOf)', () => {
      const clause = buildAsOfWhereClause('InstitutionalChip', FUTURE_DATE);
      expect(clause.prismaWhere.date.lte).toBe('20261231');
    });

    it('B6: tableName is preserved in return value', () => {
      const clause = buildAsOfWhereClause('StockQuote', VALID_DATE);
      expect(clause.tableName).toBe('StockQuote');
    });
  });

  // ── Stock detail as-of gate behavior ─────────────────────────

  describe('Stock detail as-of gate contract', () => {
    it('C1: asOfDate from query param should be resolvable', () => {
      // Simulate route behavior: extract query param → resolveAsOfDate
      const queryParam = '2026-05-01';
      const resolved = resolveAsOfDate(queryParam);
      expect(resolved).toBe('2026-05-01');
    });

    it('C2: asOfDateDb (YYYYMMDD) used in stockQuote where clause', () => {
      const asOfDate = resolveAsOfDate('2026-05-01');
      const asOfDateDb = asOfDate.replace(/-/g, '');
      expect(asOfDateDb).toBe('20260501');
      // Verify this matches what buildAsOfWhereClause produces
      const clause = buildAsOfWhereClause('StockQuote', '2026-05-01');
      expect(clause.prismaWhere.date.lte).toBe(asOfDateDb);
    });

    it('C3: future rows are excluded when asOfDateDb is set', () => {
      const asOfDateDb = '20260507'; // today
      const futureDateDb = '20260531'; // future
      // Simulating Prisma's lte filter: futureDateDb > asOfDateDb → excluded
      expect(futureDateDb > asOfDateDb).toBe(true);
      // The where clause { date: { lte: asOfDateDb } } correctly excludes it
      const mockRows = [
        { date: '20260505', close: 100 },
        { date: '20260507', close: 102 },
        { date: '20260531', close: 105 }, // future row
      ];
      const filtered = mockRows.filter(r => r.date <= asOfDateDb);
      expect(filtered.length).toBe(2);
      expect(filtered.every(r => r.date <= asOfDateDb)).toBe(true);
    });

    it('C4: no future rows leak through lte filter', () => {
      const asOfDateDb = '20260507';
      const rows = [
        { date: '20260501' }, { date: '20260507' }, { date: '20260508' },
      ];
      const gated = rows.filter(r => r.date <= asOfDateDb);
      expect(gated.every(r => r.date <= asOfDateDb)).toBe(true);
      expect(gated.find(r => r.date > asOfDateDb)).toBeUndefined();
    });
  });

  // ── History route BLOCKED contract ──────────────────────────

  describe('Stock history route BLOCKED documentation', () => {
    it('D1: history route cannot enforce asOf gate (external proxy)', () => {
      // This test documents the known limitation
      // /api/stocks/[id]/history calls twseApi.getHistorySeries() which is external
      const blockedReason = 'External API proxy (twseApi.getHistorySeries). No DB queries. Cannot add date <= asOfDate filter.';
      expect(blockedReason).toContain('External API proxy');
    });

    it('D2: mitigation: history route should be documented as BLOCKED in P0-02A artifact', () => {
      const mitigation = 'P0-03: wrap twseApi.getHistorySeries() with date filter at consumer level, or add as-of quarantine middleware.';
      expect(mitigation).toContain('P0-03');
    });
  });

  // ── Future date row behavior ──────────────────────────────────

  describe('Future date row protection', () => {
    it('E1: rows with date > asOfDate are WARN (excluded by gate)', () => {
      const asOfDateDb = '20260507';
      const rows = [{ date: '20260520' }, { date: '20260531' }];
      const futureRows = rows.filter(r => r.date > asOfDateDb);
      expect(futureRows.length).toBe(2);
      const status = futureRows.length > 0 ? 'WARN_FUTURE_ROWS_IN_DB' : 'READY';
      expect(status).toBe('WARN_FUTURE_ROWS_IN_DB');
    });

    it('E2: rows with date > asOfDate cause FAIL if they leak into response', () => {
      const asOfDateDb = '20260507';
      const responseRows = [{ date: '20260520' }]; // leaked future row
      const leaked = responseRows.filter(r => r.date > asOfDateDb);
      // Any leak = FAIL
      expect(leaked.length).toBeGreaterThan(0);
      const gateStatus = leaked.length > 0 ? 'FAIL_FUTURE_ROWS_LEAKED' : 'PASS';
      expect(gateStatus).toBe('FAIL_FUTURE_ROWS_LEAKED');
    });

    it('E3: rows with date <= asOfDate pass the gate with PASS status', () => {
      const asOfDateDb = '20260507';
      const responseRows = [{ date: '20260505' }, { date: '20260507' }];
      const leaked = responseRows.filter(r => r.date > asOfDateDb);
      expect(leaked.length).toBe(0);
      const gateStatus = leaked.length === 0 ? 'PASS' : 'FAIL';
      expect(gateStatus).toBe('PASS');
    });
  });

  // ── No strategy mutation ──────────────────────────────────────

  describe('No strategy mutation guardrail', () => {
    it('F1: buildAsOfWhereClause does not mutate scoring or weights', () => {
      const clause = buildAsOfWhereClause('StockQuote', VALID_DATE);
      // prismaWhere only contains date field
      const prismaKeys = Object.keys(clause.prismaWhere);
      expect(prismaKeys).toEqual(['date']);
    });

    it('F2: resolveAsOfDate does not affect scoring logic', () => {
      const date = resolveAsOfDate('2026-05-01');
      // resolveAsOfDate only returns a date string
      expect(typeof date).toBe('string');
      expect(date).toMatch(/^\d{4}-\d{2}-\d{2}$/);
    });
  });

  // ── No performance claims ─────────────────────────────────────

  describe('No performance claims guardrail', () => {
    it('G1: as-of gate integration does not produce performance claims', () => {
      const gateOutput = {
        asOfDate: VALID_DATE,
        asOfGateStatus: 'ACTIVE',
        futureRowsDetected: false,
        readinessStatus: 'READY',
      };
      const keys = Object.keys(gateOutput).join(' ');
      const forbidden = ['roi', 'win_rate', 'alpha', 'edge', 'profit', 'outperform', 'buy', 'sell'];
      for (const term of forbidden) {
        expect(keys.toLowerCase()).not.toContain(term.toLowerCase());
      }
    });
  });

  // ── P0-01 regression ─────────────────────────────────────────

  describe('P0-01 regression preserved', () => {
    it('R1: InvalidAsOfDateError is exported from AsOfDataGate', () => {
      expect(InvalidAsOfDateError).toBeDefined();
      const err = new InvalidAsOfDateError('test', 'bad');
      expect(err).toBeInstanceOf(Error);
      expect(err).toBeInstanceOf(InvalidAsOfDateError);
    });

    it('R2: resolveAsOfDate returns same date when called with today', () => {
      // Idempotent — same input → same output
      expect(resolveAsOfDate('2026-01-01')).toBe('2026-01-01');
      expect(resolveAsOfDate('2026-12-31')).toBe('2026-12-31');
    });

    it('R3: buildAsOfWhereClause strips hyphens to get YYYYMMDD in prismaWhere', () => {
      expect(buildAsOfWhereClause('StockQuote', '2026-01-01').prismaWhere.date.lte).toBe('20260101');
      expect(buildAsOfWhereClause('MarketIndex', '2024-12-25').prismaWhere.date.lte).toBe('20241225');
    });
  });
});

import { prisma } from '../prisma';
import { AUTONOMOUS_JOB_REGISTRY, getAutonomousJobNames } from './autonomousJobRegistry';
import type { JobAlert, JobHealthRow, JobHealthStatus, JobHealthSummary, JobRunLogRecord } from './types';

export interface JobHealthReport {
  jobs: JobHealthRow[];
  alerts: JobAlert[];
  summary: string;
  limitations: string[];
  healthSummary: JobHealthSummary;
}

function startOfUtcDay(date: Date): Date {
  return new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate()));
}

function startOfUtcWeek(date: Date): Date {
  const day = date.getUTCDay();
  const offset = day === 0 ? 6 : day - 1;
  const start = new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate()));
  start.setUTCDate(start.getUTCDate() - offset);
  return start;
}

function minutesAgo(date: Date, minutes: number): Date {
  return new Date(date.getTime() - minutes * 60_000);
}

function getWindowStart(jobName: string, now: Date): Date {
  const definition = AUTONOMOUS_JOB_REGISTRY[jobName as keyof typeof AUTONOMOUS_JOB_REGISTRY];
  if (definition?.cadence === 'interval') {
    return minutesAgo(now, (definition.intervalMinutes ?? 30) * 2);
  }
  if (definition?.cadence === 'weekly' || jobName === 'autonomous:learning') return startOfUtcWeek(now);
  return startOfUtcDay(now);
}

function getWindowLabel(jobName: string): string {
  const definition = AUTONOMOUS_JOB_REGISTRY[jobName as keyof typeof AUTONOMOUS_JOB_REGISTRY];
  if (definition?.cadence === 'interval') {
    return `recent ${(definition.intervalMinutes ?? 30) * 2} minutes`;
  }
  if (definition?.cadence === 'weekly' || jobName === 'autonomous:learning') return 'current week';
  return 'today';
}

function countConsecutiveFailures(runs: JobRunLogRecord[]): number {
  let count = 0;
  for (const run of runs) {
    if (run.status !== 'failed') break;
    count += 1;
  }
  return count;
}

function findLatestSuccessfulRun(runs: JobRunLogRecord[]): JobRunLogRecord | null {
  return runs.find((run) => run.status === 'success') ?? null;
}

function buildAlert(jobName: string, severity: JobAlert['severity'], message: string, detectedAt: Date): JobAlert {
  return {
    jobName,
    severity,
    message,
    detectedAt: detectedAt.toISOString(),
  };
}

function healthStatusForRun(
  jobName: string,
  latestRun: JobRunLogRecord | null,
  successInWindow: JobRunLogRecord | null,
  failureStreak: number,
  hasAnyHistoricalRun: boolean,
): JobHealthStatus {
  if (!latestRun && !hasAnyHistoricalRun) return 'never-ran';
  if (successInWindow) return 'ok';
  if (latestRun?.status === 'failed') return 'failed';
  if (failureStreak >= 2) return 'failed';
  if (!hasAnyHistoricalRun) return 'never-ran';
  if (jobName === 'autonomous:monitor' && latestRun?.status === 'running') return 'delayed';
  return 'delayed';
}

function healthReasonForStatus(status: JobHealthStatus, windowLabel: string, latestRun: JobRunLogRecord | null): string {
  if (status === 'ok') return `A successful run exists within the ${windowLabel} window.`;
  if (status === 'failed') return latestRun?.errorMessage ? `Latest run failed: ${latestRun.errorMessage}` : `Latest run failed in the ${windowLabel} window.`;
  if (status === 'never-ran') return 'No run has been recorded yet.';
  return `No successful run recorded in the ${windowLabel} window.`;
}

export class JobHealthService {
  async evaluate(now = new Date()): Promise<JobHealthReport> {
    const jobNames = getAutonomousJobNames();
    const runs = await prisma.jobRunLog.findMany({
      where: { jobName: { in: jobNames } },
      orderBy: [{ jobName: 'asc' }, { createdAt: 'desc' }],
    });

    const runsByJob = runs.reduce<Record<string, JobRunLogRecord[]>>((acc, row) => {
      const jobRuns = acc[row.jobName] ?? [];
      jobRuns.push({
        id: row.id,
        jobName: row.jobName,
        scheduledFor: row.scheduledFor,
        startedAt: row.startedAt,
        finishedAt: row.finishedAt,
        status: row.status as JobRunLogRecord['status'],
        runMode: row.runMode as JobRunLogRecord['runMode'],
        triggerSource: row.triggerSource as JobRunLogRecord['triggerSource'],
        idempotencyKey: row.idempotencyKey,
        summary: row.summary,
        errorMessage: row.errorMessage,
        metadata: row.metadata,
        createdAt: row.createdAt,
        updatedAt: row.updatedAt,
      });
      acc[row.jobName] = jobRuns;
      return acc;
    }, {});

    const jobs: JobHealthRow[] = [];
    const alerts: JobAlert[] = [];
    const counts: JobHealthSummary = {
      total: jobNames.length,
      ok: 0,
      delayed: 0,
      failed: 0,
      neverRan: 0,
    };

    for (const jobName of jobNames) {
      const jobRuns = runsByJob[jobName] ?? [];
      const latestRun = jobRuns[0] ?? null;
      const latestSuccessfulRun = findLatestSuccessfulRun(jobRuns);
      const windowStart = getWindowStart(jobName, now);
      const windowRuns = jobRuns.filter((run) => run.scheduledFor >= windowStart);
      const successInWindow = windowRuns.find((run) => run.status === 'success') ?? null;
      const failureStreak = countConsecutiveFailures(jobRuns);
      const healthStatus = healthStatusForRun(jobName, latestRun, successInWindow, failureStreak, jobRuns.length > 0);
      const windowLabel = getWindowLabel(jobName);
      const healthReason = healthReasonForStatus(healthStatus, windowLabel, latestRun);
      const missed = healthStatus !== 'ok';
      const canRerun = !latestRun || latestRun.status !== 'running';
      const status = latestRun?.status ?? 'never-ran';

      if (healthStatus === 'ok') counts.ok += 1;
      if (healthStatus === 'delayed') counts.delayed += 1;
      if (healthStatus === 'failed') counts.failed += 1;
      if (healthStatus === 'never-ran') counts.neverRan += 1;

      if (healthStatus === 'never-ran') {
        alerts.push(buildAlert(jobName, 'critical', `${jobName} has never run yet.`, now));
      } else if (healthStatus === 'failed') {
        const severity = failureStreak >= 2 ? 'critical' : 'warning';
        alerts.push(buildAlert(jobName, severity, `${jobName} is failing or has repeated failures.`, now));
      } else if (healthStatus === 'delayed') {
        const severity = jobName === 'autonomous:monitor' ? 'warning' : 'critical';
        alerts.push(buildAlert(jobName, severity, `${jobName} is missing a successful run in the ${windowLabel} window.`, now));
      }

      if (failureStreak >= 2) {
        alerts.push(buildAlert(jobName, 'critical', `${jobName} has ${failureStreak} consecutive failed runs.`, now));
      }

      const summary = latestRun?.summary ?? latestSuccessfulRun?.summary ?? 'No run recorded yet';

      jobs.push({
        jobName,
        scheduledFor: AUTONOMOUS_JOB_REGISTRY[jobName].getScheduledFor(now).toISOString(),
        latestRun,
        missed,
        canRerun,
        triggerSource: latestRun?.triggerSource ?? null,
        runMode: latestRun?.runMode ?? null,
        lastErrorMessage: latestRun?.errorMessage ?? null,
        status: latestRun?.status ?? 'never-ran',
        healthStatus,
        healthReason,
        lastSuccessfulRunAt: latestSuccessfulRun?.finishedAt?.toISOString() ?? latestSuccessfulRun?.startedAt?.toISOString() ?? null,
        failureStreak,
        summary,
        limitations: jobRuns.length === 0 ? ['No job run recorded yet.'] : [],
      });
    }

    const summary = [
      `${counts.total} autonomous jobs tracked.`,
      counts.failed > 0 ? `${counts.failed} job(s) are failing.` : null,
      counts.delayed > 0 ? `${counts.delayed} job(s) are delayed.` : null,
      counts.neverRan > 0 ? `${counts.neverRan} job(s) have never run.` : null,
    ]
      .filter((value): value is string => Boolean(value))
      .join(' ');

    return {
      jobs,
      alerts,
      summary,
      limitations: [
        'Health checks are computed from the current local job registry windows.',
        'A single alert may appear alongside a delayed status when a job misses its expected window.',
      ],
      healthSummary: counts,
    };
  }
}

/**
 * SchedulerStateEngine
 *
 * Responsible for startup reconciliation, backfill decisions, and scheduler
 * health state.  This module is the single source of truth for:
 *
 *   - whether a job window already ran
 *   - whether a missed window should be backfilled
 *   - which triggerSource / runMode to use for each run type
 *
 * Trigger flow:
 *   Scheduler boot → reconcile() → for each job → classify → backfill if policy allows
 *   Scheduler tick  → checkDue()  → run if window not yet satisfied
 */

import { prisma } from '../prisma';
import {
  AUTONOMOUS_JOB_REGISTRY,
  buildAutonomousIdempotencyKey,
  getAutonomousJobNextDueAt,
  getAutonomousJobNames,
} from './autonomousJobRegistry';
import {
  runAutonomousDailyCycle,
  runAutonomousLearningCycle,
  runAutonomousMonitorCycle,
  runAutonomousReviewCycle,
  runTrainingIntradayMonitorCycle,
  runTrainingDailyCycle,
  runTrainingNightlyOpt,
  runTrainingTaiwanDataSync,
  runTrainingTaiwanInsightIngest,
  runTrainingTaiwanOptimizationMiner,
  runTrainingTaiwanReport,
  runTrainingTaiwanScreen,
  runTrainingTaiwanSelfAudit,
  runTrainingTaiwanSnapshot,
  runTrainingTaiwanWeeklyDeepResearch,
  runTrainingTaiwanWorkerCycle,
  runTrainingWeeklyDeep,
} from './autonomousJobRunners';
import type { AutonomousJobName, JobExecutionResult, JobRunMode } from './types';

// ---------------------------------------------------------------------------
// Public types
// ---------------------------------------------------------------------------

/** Classification of a single job window at evaluation time. */
export type JobWindowClassification =
  | 'already_ran'   // idempotency key exists with any non-failed terminal state
  | 'not_due_yet'   // scheduledFor is in the future (edge-case guard)
  | 'missed'        // no success record for this window
  | 'failed'        // a failed record exists (eligible for retry)
  | 'never_ran';    // no runs of this job at all in history

export interface JobReconciliationResult {
  jobName: AutonomousJobName;
  scheduledFor: Date;
  classification: JobWindowClassification;
  backfillDecision: 'backfill' | 'skip';
  skipReason?: string;
  backfilled: boolean;
  backfillRunId?: number;
  errorMessage?: string;
}

export interface SchedulerStatus {
  schedulerPid: number | null;
  lastReconciliationAt: string | null;
  uptimeSeconds: number | null;
  missedJobCount: number;
  backfilledJobCount: number;
  neverRanJobs: string[];
  nextScheduledJobs: Array<{ jobName: string; nextDueAt: string }>;
  reconciliationResults: JobReconciliationResult[];
  jobSummary: Array<{
    jobName: string;
    lastRunAt: string | null;
    lastStatus: string | null;
    windowClassification: JobWindowClassification;
  }>;
}

// ---------------------------------------------------------------------------
// Backfill policy
// ---------------------------------------------------------------------------

interface BackfillPolicy {
  /** Whether to automatically backfill a missed window. */
  autoBackfill: boolean;
  /** Max age (ms) of a missed window that is still eligible for backfill.
   *  null = no age limit (always backfill). */
  maxMissedAgeMs: number | null;
  /** For interval jobs: only backfill the single most-recent missed window. */
  mostRecentOnly: boolean;
}

type BackfillTriggerSource = 'local_scheduler';

type BackfillRunner = (args: {
  triggerSource: BackfillTriggerSource;
  scheduledFor: Date;
  runMode: JobRunMode;
}) => Promise<JobExecutionResult<unknown>>;

