export const PREVIEW_VERSION = 'daily-snapshot-append-preview-v0';

// ─── Forbidden claims ────────────────────────────────────────────────────────

const FORBIDDEN_PATTERNS = [
    /\bprofit\b/i,
    /\bguaranteed\b/i,
    /\bedge confirmed\b/i,
    /\bproduction approved\b/i,
    /\bauto trading\b/i,
