// ─── Build Replay Dataset Key ──────────────────────────────────────

export function buildReplayDatasetKey(
    entry: Pick<ReplaySourceLedgerEntry, 'asOfDate' | 'symbol' | 'universeTier' | 'runId'>,
    horizonLabel: string
): string {
    return `REPLAY_DATASET|${entry.asOfDate}|${entry.symbol}|${entry.universeTier}|${entry.runId}|${horizonLabel}`;
}

// ─── Parse Source Artifacts ────────────────────────────────────────

export function parseReplaySourceArtifacts(input: {
    ledgerContent: string;
    outcomeWindowResult: unknown;
    outcomeWriteBackJsonlContent?: string;
    backfillPlan?: unknown;
}): ParsedReplaySourceArtifacts {
    const messages: string[] = [];
    let validationStatus: 'PASS' | 'WARN' | 'FAIL' = 'PASS';

    // Parse ledger JSONL
    const ledgerEntries: ReplaySourceLedgerEntry[] = [];
    const ledgerLines = input.ledgerContent.trim().split('\n').filter(Boolean);
    for (let i = 0; i < ledgerLines.length; i++) {
        try {
            const obj = JSON.parse(ledgerLines[i]);
            if (obj.entryType === 'SHADOW_PREDICTION') {
                ledgerEntries.push(obj as ReplaySourceLedgerEntry);
            }
        } catch {
            validationStatus = 'FAIL';
            messages.push(`FAIL: Malformed JSONL on ledger line ${i + 1}`);
        }
    }

    // Parse outcome window result
    let windows: OutcomeWindowRecord[] = [];
    if (input.outcomeWindowResult && typeof input.outcomeWindowResult === 'object') {
        const r = input.outcomeWindowResult as { windows?: unknown[] };
        if (Array.isArray(r.windows)) {
            windows = r.windows as OutcomeWindowRecord[];
        }
    }

    // Parse p1 outcome records (optional)
    const outcomeRecords: P1OutcomeRecord[] = [];
    if (input.outcomeWriteBackJsonlContent) {
        const oLines = input.outcomeWriteBackJsonlContent.trim().split('\n').filter(Boolean);
        for (let i = 0; i < oLines.length; i++) {
            try {
                const obj = JSON.parse(oLines[i]);
                outcomeRecords.push(obj as P1OutcomeRecord);
            } catch {
                validationStatus = validationStatus === 'FAIL' ? 'FAIL' : 'WARN';
                messages.push(`WARN: Malformed JSONL on outcome line ${i + 1}`);
            }
        }
    } else {
        validationStatus = validationStatus === 'FAIL' ? 'FAIL' : 'WARN';
        messages.push('WARN: outcomeWriteBackJsonlContent not provided — outcome matching will be skipped');
    }

    // Parse backfill plan
    const scheduledBackfillItems: BackfillScheduleItem[] = [];
    if (input.backfillPlan && typeof input.backfillPlan === 'object') {
        const bp = input.backfillPlan as { scheduledItems?: unknown[] };
        if (Array.isArray(bp.scheduledItems)) {
            scheduledBackfillItems.push(...bp.scheduledItems as BackfillScheduleItem[]);
        }
    }

    return { ledgerEntries, windows, outcomeRecords, scheduledBackfillItems, validationStatus, validationMessages: messages };
}

// ─── Build Replay Dataset ─────────────────────────────────────────

export function buildReplayDataset(
    input: BuildReplayDatasetInput,
    options: BuildReplayDatasetOptions
): ReplayDataset {
    const { replayRunId, reviewDate, horizons = [5, 20, 60], requireOutcomeForDueWindows = false } = options;
    const messages: string[] = [];
    let validationStatus: 'PASS' | 'WARN' | 'FAIL' = 'PASS';
    const records: ReplayRecord[] = [];

    // Build outcome lookup: key=(symbol|horizonLabel|asOfDate)
    const outcomeMap = new Map<string, P1OutcomeRecord>();
    for (const rec of input.outcomeRecords) {
        const asOfDate = rec.originalAsOfDate ?? '';
        const key = `${rec.symbol}|${rec.horizonLabel}|${asOfDate}`;
        outcomeMap.set(key, rec);
    }

    // Build window lookup: key=(symbol|horizonLabel|asOfDate)
    const windowMap = new Map<string, OutcomeWindowRecord>();
    for (const w of input.windows) {
        const key = `${w.symbol}|${w.horizonLabel}|${w.originalAsOfDate}`;
        windowMap.set(key, w);
    }

    const HORIZON_LABELS: Record<number, string> = { 5: '5D', 20: '20D', 60: '60D' };

    for (const entry of input.ledgerEntries) {
        if (!entry.symbol || !entry.asOfDate || !entry.runId || !entry.universeTier) {
            messages.push(`WARN: Ledger entry missing required fields, skipping`);
            continue;
        }

        // PIT check
        const sourceDate = entry.sourceDateBasis?.sourceDate ?? '';
        const isPitViolation = sourceDate > entry.asOfDate;
        const pitSafeStatus = isPitViolation ? 'PIT_VIOLATION' : 'PIT_SAFE';

        for (const horizonDays of horizons) {
            const horizonLabel = HORIZON_LABELS[horizonDays] ?? `${horizonDays}D`;
            const replayKey = buildReplayDatasetKey(entry, horizonLabel);

            const recMessages: string[] = [];
            let replayEligible = false;
            let replayBlockedReason: ReplayBlockedReason = 'NONE';
            let outcomeStatus: ReplayOutcomeStatus = 'PENDING';

            // Look up window
            const windowKey = `${entry.symbol}|${horizonLabel}|${entry.asOfDate}`;
            const window = windowMap.get(windowKey);

            if (!window) {
                recMessages.push(`WARN: No matching window for ${windowKey}`);
            }

            const targetTradingDate = window?.targetTradingDate ?? '';
            const windowStatus = window?.windowStatus ?? 'BLOCKED';

            // PIT safety check
            if (isPitViolation) {
                replayBlockedReason = 'PIT_VIOLATION';
                recMessages.push(`FAIL: sourceDate=${sourceDate} > asOfDate=${entry.asOfDate}`);
                outcomeStatus = 'BLOCKED';
            } else if (!targetTradingDate || targetTradingDate <= entry.asOfDate) {
                replayBlockedReason = 'TARGET_DATE_INVALID';
                recMessages.push(`FAIL: targetTradingDate=${targetTradingDate} must be > asOfDate=${entry.asOfDate}`);
                outcomeStatus = 'BLOCKED';
            } else if (reviewDate < targetTradingDate) {
                replayBlockedReason = 'WINDOW_NOT_DUE';
                recMessages.push(`WARN: reviewDate=${reviewDate} < targetTradingDate=${targetTradingDate} — not due`);
                outcomeStatus = 'NOT_DUE';
            } else if (entry.validationStatus && entry.validationStatus !== 'PASS') {
                replayBlockedReason = 'VALIDATION_FAIL';
                recMessages.push(`FAIL: validationStatus=${entry.validationStatus}`);
                outcomeStatus = 'BLOCKED';
            } else {
                // Due window — look up outcome
                const outcomeKey = `${entry.symbol}|${horizonLabel}|${entry.asOfDate}`;
                const outcome = outcomeMap.get(outcomeKey);

                if (!outcome) {
                    recMessages.push(`WARN: No p1 outcome record found for ${outcomeKey}`);
                    outcomeStatus = 'MISSING_PRICE';
                    replayBlockedReason = 'OUTCOME_MISSING';
                    if (requireOutcomeForDueWindows) {
                        validationStatus = validationStatus === 'FAIL' ? 'FAIL' : 'WARN';
                        messages.push(`WARN: requireOutcomeForDueWindows=true but outcome missing for ${outcomeKey}`);
                    }
                } else if (outcome.outcomeStatus === 'READY_FOR_REVIEW' && outcome.closePriceAtOutcome != null) {
                    outcomeStatus = 'READY_FOR_REVIEW';
                    replayEligible = true;
                    replayBlockedReason = 'NONE';
                } else if (outcome.outcomeStatus === 'MISSING_PRICE') {
                    outcomeStatus = 'MISSING_PRICE';
                    replayBlockedReason = 'OUTCOME_MISSING';
                    recMessages.push(`WARN: outcomeStatus=MISSING_PRICE for ${outcomeKey}`);
                } else {
                    outcomeStatus = (outcome.outcomeStatus as ReplayOutcomeStatus) ?? 'PENDING';
                    replayBlockedReason = 'OUTCOME_MISSING';
                }
            }

            // Build outcomeSnapshot
            const outcomeKey = `${entry.symbol}|${horizonLabel}|${entry.asOfDate}`;
            const outcomeRecord = outcomeMap.get(outcomeKey);
            const outcomeSnapshot: OutcomeSnapshot = {
                closePriceAtPrediction: outcomeRecord?.closePriceAtPrediction ?? null,
                closePriceAtOutcome: outcomeRecord?.closePriceAtOutcome ?? null,
                returnPct: outcomeRecord?.returnPct ?? null,
                priceSource: outcomeRecord?.priceSource ?? null,
                outcomeAvailable: replayEligible,
            };

            const record: ReplayRecord = {
                replayDatasetVersion: REPLAY_DATASET_VERSION,
                replayRunId,
                replayKey,
                originalRunId: entry.runId,
                originalAsOfDate: entry.asOfDate,
                symbol: entry.symbol,
                stockName: entry.stockName ?? '',
                universeTier: entry.universeTier,
                horizonLabel,
                horizonDays,
                targetTradingDate,
                reviewDate,
                windowStatus,
                outcomeStatus,
                researchBucket: entry.researchBucket ?? '',
                scoreSnapshot: (entry.scoreSnapshot as Record<string, unknown>) ?? {},
                confidenceSnapshot: entry.confidenceSnapshot ?? null,
                factorSnapshot: entry.factorSnapshot ?? [],
                riskSnapshot: entry.riskSnapshot ?? [],
                limitationSnapshot: entry.limitationSnapshot ?? [],
                dataCoverageSnapshot: entry.dataCoverageSnapshot ?? null,
                sourceDateBasis: entry.sourceDateBasis ?? null,
                outcomeSnapshot,
                pitSafeStatus,
                replayEligible,
                replayBlockedReason,
                productionWriteAllowed: false,
                simulationWriteAllowed: false,
                validationMessages: recMessages,
            };

            records.push(record);
        }
    }

    const eligibleCount = records.filter(r => r.replayEligible).length;
    const blockedCount = records.filter(r => !r.replayEligible).length;

    return {
        replayDatasetVersion: REPLAY_DATASET_VERSION,
        replayRunId,
        reviewDate,
        records,
        totalRecords: records.length,
        eligibleCount,
        blockedCount,
        validationStatus,
        validationMessages: messages,
    };
}

// ─── Summarize Replay Dataset ─────────────────────────────────────

export function summarizeReplayDataset(dataset: ReplayDataset): ReplayDatasetSummary {
    const byHorizon: Record<string, number> = {};
    const byWindowStatus: Record<string, number> = {};
    const byOutcomeStatus: Record<string, number> = {};
    const byReplayBlockedReason: Record<string, number> = {};
    const symbolSet = new Set<string>();
    const asOfDates: string[] = [];
    const targetDates: string[] = [];

    for (const r of dataset.records) {
        byHorizon[r.horizonLabel] = (byHorizon[r.horizonLabel] || 0) + 1;
        byWindowStatus[r.windowStatus] = (byWindowStatus[r.windowStatus] || 0) + 1;
        byOutcomeStatus[r.outcomeStatus] = (byOutcomeStatus[r.outcomeStatus] || 0) + 1;
        byReplayBlockedReason[r.replayBlockedReason] = (byReplayBlockedReason[r.replayBlockedReason] || 0) + 1;
        symbolSet.add(r.symbol);
        if (r.originalAsOfDate) asOfDates.push(r.originalAsOfDate);
        if (r.targetTradingDate) targetDates.push(r.targetTradingDate);
    }

    asOfDates.sort();
    targetDates.sort();

    return {
        totalRecords: dataset.totalRecords,
        eligibleCount: dataset.eligibleCount,
        blockedCount: dataset.blockedCount,
        byHorizon,
        byWindowStatus,
        byOutcomeStatus,
        byReplayBlockedReason,
        symbolCount: symbolSet.size,
        earliestAsOfDate: asOfDates[0] ?? null,
        latestAsOfDate: asOfDates[asOfDates.length - 1] ?? null,
        earliestTargetTradingDate: targetDates[0] ?? null,
        latestTargetTradingDate: targetDates[targetDates.length - 1] ?? null,
    };
}

// ─── Validate Replay Dataset ─────────────────────────────────────

export function validateReplayDataset(dataset: ReplayDataset): ValidateReplayDatasetResult {
    const messages: string[] = [];
    let status: 'PASS' | 'WARN' | 'FAIL' = 'PASS';
    let forbiddenClaimFound = false;

    // reviewDate format
    if (!/^\d{4}-\d{2}-\d{2}$/.test(dataset.reviewDate)) {
        status = 'FAIL';
        messages.push(`FAIL: reviewDate=${dataset.reviewDate} is not YYYY-MM-DD`);
    }

    for (const r of dataset.records) {
        // productionWriteAllowed must be false
        if (r.productionWriteAllowed !== false) {
            status = 'FAIL';
            messages.push(`FAIL: productionWriteAllowed must be false for ${r.replayKey}`);
        }
        // simulationWriteAllowed must be false
        if (r.simulationWriteAllowed !== false) {
            status = 'FAIL';
            messages.push(`FAIL: simulationWriteAllowed must be false for ${r.replayKey}`);
        }
        // targetTradingDate > originalAsOfDate
        if (r.targetTradingDate && r.originalAsOfDate && r.targetTradingDate <= r.originalAsOfDate) {
            status = 'FAIL';
            messages.push(`FAIL: targetTradingDate=${r.targetTradingDate} must be > asOfDate=${r.originalAsOfDate} for ${r.replayKey}`);
        }
        // If replayEligible, must have outcomeAvailable
        if (r.replayEligible && !r.outcomeSnapshot.outcomeAvailable) {
            status = 'FAIL';
            messages.push(`FAIL: replayEligible=true but outcomeAvailable=false for ${r.replayKey}`);
        }
        // Check forbidden claims in messages
        const allText = [...r.validationMessages].join(' ');
        if (hasForbiddenClaim(allText)) {
            forbiddenClaimFound = true;
            status = 'FAIL';
            messages.push(`FAIL: forbidden claim found in validationMessages for ${r.replayKey}`);
        }
    }

    // Check forbidden claims in dataset messages
    const dsText = dataset.validationMessages.join(' ');
    if (hasForbiddenClaim(dsText)) {
        forbiddenClaimFound = true;
        status = 'FAIL';
        messages.push('FAIL: forbidden claim found in dataset validationMessages');
    }

    if (status === 'PASS') messages.push('PASS: All replay dataset validation checks passed');

    return { validationStatus: status, validationMessages: messages, forbiddenClaimFound };
}

/**
 * MonthlyRevenueAvailability.ts
 *
 * DISCLAIMER: Does not constitute investment advice. Does not compute ROI,
 * profit, alpha, win-rate, edge, or outperformance. Governance / PIT gate only.
 *
 * P17-HARDRESET: MonthlyRevenue releaseDate PIT availability helper.
 *
 * Rules:
 * 1. releaseDate present → available iff releaseDate <= asOfDate
 * 2. releaseDate missing + allowInferredReleaseDate=true → infer next-month-10th,
 *    releaseDateSource=INFERRED_NEXT_MONTH_10TH, releaseDateConfidence=LOW_TO_MEDIUM
 * 3. releaseDate missing + allowInferredReleaseDate=false → unavailable
 * 4. missing year/month → unavailable
 * 5. invalid month (0 or >12) → unavailable
 * 6. No outcome / returnPct / realizedReturnClass used
 * 7. Deterministic (no Math.random)
 */

// ─── Constants ──────────────────────────────────────────────────────────────

export const TAIWAN_REVENUE_RELEASE_DAY = 10;
export const INFERRED_RELEASE_DATE_SOURCE = 'INFERRED_NEXT_MONTH_10TH';
export const INFERRED_RELEASE_DATE_CONFIDENCE = 'LOW_TO_MEDIUM';

// ─── Types ──────────────────────────────────────────────────────────────────

export interface MonthlyRevenueRecord {
  stockId?: string | null;
  year: number | null | undefined;
  month: number | null | undefined;
  revenue?: number | null;
  releaseDate?: string | Date | null;
  releaseDateSource?: string | null;
  releaseDateConfidence?: string | null;
}

export interface MonthlyRevenueAvailabilityOptions {
  /** Allow falling back to inferred release date when explicit is missing */
  allowInferredReleaseDate?: boolean;
}

export interface MonthlyRevenueAvailabilityResult {
  available: boolean;
  stockId?: string | null;
  year?: number | null;
  month?: number | null;
  releaseDate: string | null;
  releaseDateSource: string | null;
  releaseDateConfidence: string | null;
  asOfDate: string;
  reason: string;
  inferred: boolean;
}

export interface MonthlyRevenueAvailabilityExplanation extends MonthlyRevenueAvailabilityResult {
  rule: string;
  details: string;
}

// ─── Internal helpers ────────────────────────────────────────────────────────

/**
 * Compute the inferred release date for a given year/month.
 * Taiwan rule: revenue released on the 10th of the following month.
 * month=12 → year+1, month=1 → DATE(year+1, 1, 10)
 */
function inferReleaseDateString(year: number, month: number): string {
  if (month === 12) {
    return `${year + 1}-01-${String(TAIWAN_REVENUE_RELEASE_DAY).padStart(2, '0')}`;
  }
  return `${year}-${String(month + 1).padStart(2, '0')}-${String(TAIWAN_REVENUE_RELEASE_DAY).padStart(2, '0')}`;
}

/**
 * Normalize a releaseDate value to an ISO date string (YYYY-MM-DD) or null.
 * Accepts Date objects or string. Does not interpret outcome/return fields.
 */
function toDateString(value: string | Date | null | undefined): string | null {
  if (value === null || value === undefined || value === '') return null;
  if (value instanceof Date) {
    // Use UTC date parts to avoid timezone shift
    const y = value.getUTCFullYear();
    const m = String(value.getUTCMonth() + 1).padStart(2, '0');
    const d = String(value.getUTCDate()).padStart(2, '0');
    return `${y}-${m}-${d}`;
  }
  // Accept YYYY-MM-DD or ISO 8601
  const s = String(value).trim();
  const match = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (match) return `${match[1]}-${match[2]}-${match[3]}`;
  return null;
}

/**
 * Compare two YYYY-MM-DD strings lexicographically (works for ISO dates).
 * Returns negative if a < b, 0 if equal, positive if a > b.
 */
function compareDates(a: string, b: string): number {
  return a < b ? -1 : a > b ? 1 : 0;
}

// ─── Exported API ────────────────────────────────────────────────────────────

/**
 * Infer the release date for a MonthlyRevenue record if it is missing.
 * Returns null if year/month is invalid.
 */
export function inferMonthlyRevenueReleaseDate(
  record: MonthlyRevenueRecord,
  _options?: MonthlyRevenueAvailabilityOptions,
): { releaseDate: string | null; releaseDateSource: string; releaseDateConfidence: string } | null {
  const year = record.year;
  const month = record.month;
  if (year === null || year === undefined || month === null || month === undefined) return null;
  if (!Number.isInteger(month) || month < 1 || month > 12) return null;
  if (!Number.isInteger(year) || year < 1900 || year > 9999) return null;
  return {
    releaseDate: inferReleaseDateString(year, month),
    releaseDateSource: INFERRED_RELEASE_DATE_SOURCE,
    releaseDateConfidence: INFERRED_RELEASE_DATE_CONFIDENCE,
  };
}

/**
 * Normalize a MonthlyRevenue record's releaseDate to a canonical string.
 * If present (any format), converts to YYYY-MM-DD.
 */
export function normalizeMonthlyRevenueReleaseDate(
  record: MonthlyRevenueRecord,
): { releaseDate: string | null; releaseDateSource: string | null; releaseDateConfidence: string | null } {
  const normalized = toDateString(record.releaseDate);
  return {
    releaseDate: normalized,
    releaseDateSource: record.releaseDateSource ?? null,
    releaseDateConfidence: record.releaseDateConfidence ?? null,
  };
}

/**
 * Core PIT gate: determine if a MonthlyRevenue record is available as of a given date.
 *
 * Rules applied in order:
 * 1. Invalid year/month → unavailable
 * 2. releaseDate present → available iff releaseDate <= asOfDate
 * 3. releaseDate missing + allowInferredReleaseDate=true → infer + apply rule 2
 * 4. releaseDate missing + allowInferredReleaseDate=false → unavailable
 */
export function isMonthlyRevenueAvailableAsOf(
  record: MonthlyRevenueRecord,
  asOfDate: string,
  options?: MonthlyRevenueAvailabilityOptions,
): MonthlyRevenueAvailabilityResult {
  const allowInferred = options?.allowInferredReleaseDate ?? false;
  const baseResult = {
    stockId: record.stockId ?? null,
    year: record.year,
    month: record.month,
    asOfDate,
  };

  // Rule 4: missing year/month
  if (record.year === null || record.year === undefined) {
    return {
      ...baseResult,
      available: false,
      releaseDate: null,
      releaseDateSource: null,
      releaseDateConfidence: null,
      reason: 'missing year — unavailable',
      inferred: false,
    };
  }
  if (record.month === null || record.month === undefined) {
    return {
      ...baseResult,
      available: false,
      releaseDate: null,
      releaseDateSource: null,
      releaseDateConfidence: null,
      reason: 'missing month — unavailable',
      inferred: false,
    };
  }

  // Rule 5: invalid month
  if (!Number.isInteger(record.month) || record.month < 1 || record.month > 12) {
    return {
      ...baseResult,
      available: false,
      releaseDate: null,
      releaseDateSource: null,
      releaseDateConfidence: null,
      reason: `invalid month ${record.month} — unavailable`,
      inferred: false,
    };
  }

  // Rule 2: explicit releaseDate present
  const explicitReleaseDate = toDateString(record.releaseDate);
  if (explicitReleaseDate !== null) {
    const isInferred = record.releaseDateSource === INFERRED_RELEASE_DATE_SOURCE;
    if (isInferred && !allowInferred) {
      return {
        ...baseResult,
        available: false,
        releaseDate: explicitReleaseDate,
        releaseDateSource: record.releaseDateSource ?? null,
        releaseDateConfidence: record.releaseDateConfidence ?? null,
        reason: `inferred releaseDate but allowInferredReleaseDate=false — unavailable`,
        inferred: true,
      };
    }
    const available = compareDates(explicitReleaseDate, asOfDate) <= 0;
    return {
      ...baseResult,
      available,
      releaseDate: explicitReleaseDate,
      releaseDateSource: record.releaseDateSource ?? null,
      releaseDateConfidence: record.releaseDateConfidence ?? null,
      reason: available
        ? `releaseDate (${explicitReleaseDate}) <= asOfDate (${asOfDate}) — available`
        : `releaseDate (${explicitReleaseDate}) > asOfDate (${asOfDate}) — unavailable`,
      inferred: isInferred,
    };
  }

  // Rule 3: inferred
  if (allowInferred) {
    const inferred = inferMonthlyRevenueReleaseDate(record);
    if (inferred && inferred.releaseDate) {
      const available = compareDates(inferred.releaseDate, asOfDate) <= 0;
      return {
        ...baseResult,
        available,
        releaseDate: inferred.releaseDate,
        releaseDateSource: inferred.releaseDateSource,
        releaseDateConfidence: inferred.releaseDateConfidence,
        reason: available
          ? `inferred releaseDate (${inferred.releaseDate}) <= asOfDate (${asOfDate}) — available`
          : `inferred releaseDate (${inferred.releaseDate}) > asOfDate (${asOfDate}) — unavailable`,
        inferred: true,
      };
    }
    return {
      ...baseResult,
      available: false,
      releaseDate: null,
      releaseDateSource: null,
      releaseDateConfidence: null,
      reason: 'could not infer releaseDate — unavailable',
      inferred: false,
    };
  }

  // Rule 4: no releaseDate, no inferred allowed
  return {
    ...baseResult,
    available: false,
    releaseDate: null,
    releaseDateSource: null,
    releaseDateConfidence: null,
    reason: 'no releaseDate and allowInferredReleaseDate=false — unavailable',
    inferred: false,
  };
}

/**
 * Filter an array of MonthlyRevenue records to those available as of asOfDate.
 * Records without a releaseDate are excluded by default (allowInferredReleaseDate=false).
 */
export function filterMonthlyRevenueAvailableAsOf<T extends MonthlyRevenueRecord>(
  records: T[],
  asOfDate: string,
  options?: MonthlyRevenueAvailabilityOptions,
): T[] {
  return records.filter(record => {
    const result = isMonthlyRevenueAvailableAsOf(record, asOfDate, options);
    return result.available;
  });
}

/**
 * Validate a MonthlyRevenueAvailabilityResult for required fields.
 */
export function validateMonthlyRevenueAvailabilityResult(
  result: MonthlyRevenueAvailabilityResult,
): { valid: boolean; errors: string[] } {
  const errors: string[] = [];
  if (typeof result.available !== 'boolean') errors.push('available must be boolean');
  if (typeof result.reason !== 'string' || result.reason.trim() === '') errors.push('reason must be non-empty string');
  if (typeof result.asOfDate !== 'string') errors.push('asOfDate must be string');
  if (typeof result.inferred !== 'boolean') errors.push('inferred must be boolean');
  return { valid: errors.length === 0, errors };
}

/**
 * Produce a human-readable explanation of the availability decision.
 */
export function explainMonthlyRevenueAvailability(
  record: MonthlyRevenueRecord,
  asOfDate: string,
  options?: MonthlyRevenueAvailabilityOptions,
): MonthlyRevenueAvailabilityExplanation {
  const result = isMonthlyRevenueAvailableAsOf(record, asOfDate, options);
  let rule: string;
  let details: string;

  if (!result.available && (record.year === null || record.year === undefined)) {
    rule = 'RULE_4_MISSING_YEAR';
    details = 'Record has no year — cannot determine availability';
  } else if (!result.available && (record.month === null || record.month === undefined)) {
    rule = 'RULE_4_MISSING_MONTH';
    details = 'Record has no month — cannot determine availability';
  } else if (!result.available && result.releaseDate === null && !result.inferred) {
    rule = 'RULE_4_NO_RELEASE_DATE';
    details = `No releaseDate on record for ${record.year}/${record.month}. Set allowInferredReleaseDate=true to use Taiwan 10th-of-next-month inference.`;
  } else if (result.inferred) {
    rule = result.available ? 'RULE_3_INFERRED_AVAILABLE' : 'RULE_3_INFERRED_UNAVAILABLE';
    details = `releaseDate inferred via Taiwan RELEASE_DAY=${TAIWAN_REVENUE_RELEASE_DAY}: ${result.releaseDate}. Confidence: ${result.releaseDateConfidence}.`;
  } else {
    rule = result.available ? 'RULE_2_EXPLICIT_AVAILABLE' : 'RULE_2_EXPLICIT_UNAVAILABLE';
    details = `Explicit releaseDate=${result.releaseDate}, asOfDate=${asOfDate}.`;
  }

  return { ...result, rule, details };
}

/**
 * OutcomeBackfillGovernanceGate.ts — P15 Online Validation
 *
 * Governs whether an artifact-only outcome backfill rehearsal can proceed
 * to manual review planning. This does not permit any production or corpus
 * write path.
 */

import type { OutcomeBackfillCandidateSelection } from './OutcomeBackfillCandidateSelector';
import type { OutcomeBackfillRehearsal } from './OutcomeBackfillRehearsalEngine';
import type { BackfillQualityImpactPreview } from './BackfillQualityImpactPreview';
import type { CorpusQualityGateResult } from './CorpusQualityGate';
import type { CoverageRecoveryPlan } from './CoverageRecoveryPlanner';

export const OUTCOME_BACKFILL_GOVERNANCE_GATE_VERSION = 'outcome-backfill-governance-gate-v0';

const FORBIDDEN_PATTERNS = [
    /\bprofit\b/i,
    /\bguaranteed\b/i,
    /\bedge confirmed\b/i,
    /\bproduction approved\b/i,
    /\bauto trading\b/i,
    /\bbuy\b/i,
    /\bsell\b/i,
    /\boutperform\b/i,
    /\bexpected_return\b/i,
    /\bstrategy performance\b/i,
    /\bPRODUCTION_READY\b/i,
    /\bCORPUS_WRITE_READY\b/i,
    /\bOPTIMIZER_READY\b/i,
];

function hasForbiddenClaim(text: string): boolean {
    return FORBIDDEN_PATTERNS.some(pattern => pattern.test(text));
}

export type OutcomeBackfillGovernanceGateStatus =
    | 'READY_FOR_MANUAL_REVIEW'
    | 'DATA_LIMITED'
    | 'BLOCKED';

export type OutcomeBackfillGovernanceDecision =
    | 'ALLOW_MANUAL_REVIEW_ONLY'
    | 'BLOCK_WRITE_PATH'
    | 'BLOCK_INSUFFICIENT_REHEARSAL'
    | 'BLOCK_DATA_LIMITED';

export interface OutcomeBackfillGovernanceApprovalBoundary {
    manualApprovalRequired: true;
    automaticPromotionAllowed: false;
    productionBackfillAllowed: false;
    corpusWriteAllowed: false;
    optimizerAllowed: false;
    allowedNextStep: 'MANUAL_REVIEW_ONLY';
}

export interface OutcomeBackfillGovernanceWritePathPolicy {
    productionDbWriteAllowed: false;
    corpusJsonlWriteAllowed: false;
    predictionRowWriteAllowed: false;
    strategySignalWriteAllowed: false;
    artifactOnly: true;
}

export interface OutcomeBackfillGovernanceGateChecks {
    hasCandidates: boolean;
    hasRehearsalItems: boolean;
    hasBlockedToReadyTransition: boolean;
    corpusUnchanged: boolean;
    qualityImpactIsPreviewOnly: true;
    requiresManualApproval: boolean;
    noProductionWrite: true;
    noCorpusWrite: true;
    noOptimizerWrite: true;
    noPerformanceClaim: true;
    noTradingSignal: true;
}

export interface OutcomeBackfillGovernanceGateInput {
    candidateSelection: OutcomeBackfillCandidateSelection;
    rehearsal: OutcomeBackfillRehearsal;
    qualityImpactPreview: BackfillQualityImpactPreview;
    currentCorpusLineCount: number;
    currentQualityGate?: CorpusQualityGateResult;
    recoveryPlan?: CoverageRecoveryPlan;
}

export interface BuildOutcomeBackfillGovernanceGateOptions {
    governanceRunId: string;
    generatedAt: string;
    requireManualApproval?: boolean;
    minRehearsedCount?: number;
    minBlockedToReadyCount?: number;
    maxAllowedCorpusWritePermission: false;
}

export interface OutcomeBackfillGovernanceGate {
    governanceGateVersion: string;
    governanceRunId: string;
    generatedAt: string;
    inputSummary: {
        candidateCount: number;
        rehearsalItemCount: number;
        blockedToReadyCount: number;
        currentCorpusLineCount: number;
        currentQualityStatus: string | null;
        projectedQualityStatus: string;
        projectedCoverageRatio: number;
        previewOnly: true;
    };
    gateChecks: OutcomeBackfillGovernanceGateChecks;
    gateStatus: OutcomeBackfillGovernanceGateStatus;
    decision: OutcomeBackfillGovernanceDecision;
    approvalBoundary: OutcomeBackfillGovernanceApprovalBoundary;
    writePathPolicy: OutcomeBackfillGovernanceWritePathPolicy;
    riskFlags: string[];
    requiredNextApprovals: string[];
    validationStatus: 'PASS' | 'WARN' | 'FAIL';
    validationMessages: string[];
}

export interface OutcomeBackfillGovernanceValidationResult {
    validationStatus: 'PASS' | 'WARN' | 'FAIL';
    validationMessages: string[];
}

export function buildOutcomeBackfillGovernanceGate(
    input: OutcomeBackfillGovernanceGateInput,
    options: BuildOutcomeBackfillGovernanceGateOptions,
): OutcomeBackfillGovernanceGate {
    const requireManualApproval = options.requireManualApproval ?? true;
    const minRehearsedCount = options.minRehearsedCount ?? 1;
    const minBlockedToReadyCount = options.minBlockedToReadyCount ?? 1;

    const blockedToReadyCount = input.rehearsal.rehearsalItems.filter(
        item => item.transitionType === 'BLOCKED_TO_READY',
    ).length;

    const hasCandidates = input.candidateSelection.selectedCount > 0;
    const hasRehearsalItems = input.rehearsal.rehearsalItems.length >= minRehearsedCount;
    const hasBlockedToReadyTransition = blockedToReadyCount >= minBlockedToReadyCount;
    const corpusUnchanged = input.currentCorpusLineCount === 60;
    const qualityImpactIsPreviewOnly = true as const;
    const noProductionWrite =
        input.candidateSelection.candidates.every(candidate => candidate.productionWriteAllowed === false) &&
        input.rehearsal.rehearsalItems.every(item => item.productionWriteAllowed === false) &&
        input.qualityImpactPreview.guardrails.noProductionWrite === true;
    const noCorpusWrite =
        input.rehearsal.rehearsalItems.every(item => item.corpusWriteAllowed === false) &&
        input.qualityImpactPreview.guardrails.noCorpusWrite === true;
    const noOptimizerWrite =
        input.candidateSelection.candidates.every(candidate => candidate.optimizerWriteAllowed === false) &&
        input.rehearsal.rehearsalItems.every(item => item.optimizerWriteAllowed === false) &&
        input.qualityImpactPreview.guardrails.noOptimizerWrite === true;
    const noPerformanceClaim = input.qualityImpactPreview.guardrails.noPerformanceClaim === true;
    const noTradingSignal = input.qualityImpactPreview.guardrails.noTradingSignal === true;

    const gateChecks: OutcomeBackfillGovernanceGateChecks = {
        hasCandidates,
        hasRehearsalItems,
        hasBlockedToReadyTransition,
        corpusUnchanged,
        qualityImpactIsPreviewOnly,
        requiresManualApproval: requireManualApproval,
        noProductionWrite: true,
        noCorpusWrite: true,
        noOptimizerWrite: true,
        noPerformanceClaim: true,
        noTradingSignal: true,
    };

    let gateStatus: OutcomeBackfillGovernanceGateStatus;
    let decision: OutcomeBackfillGovernanceDecision;

    if (!corpusUnchanged) {
        gateStatus = 'BLOCKED';
        decision = 'BLOCK_WRITE_PATH';
    } else if (!hasCandidates || !hasRehearsalItems || !hasBlockedToReadyTransition) {
        gateStatus = 'BLOCKED';
        decision = 'BLOCK_INSUFFICIENT_REHEARSAL';
    } else if (!requireManualApproval) {
        gateStatus = 'BLOCKED';
        decision = 'BLOCK_WRITE_PATH';
    } else {
        gateStatus = 'READY_FOR_MANUAL_REVIEW';
        decision = 'ALLOW_MANUAL_REVIEW_ONLY';
    }

    if (input.currentQualityGate?.qualityStatus === 'DATA_LIMITED' && gateStatus === 'READY_FOR_MANUAL_REVIEW') {
        gateStatus = 'DATA_LIMITED';
        decision = 'BLOCK_DATA_LIMITED';
    }

    if (input.qualityImpactPreview.projectedQualityStatus === 'DATA_LIMITED' && gateStatus === 'READY_FOR_MANUAL_REVIEW') {
        gateStatus = 'DATA_LIMITED';
        decision = 'BLOCK_DATA_LIMITED';
    }

    const approvalBoundary: OutcomeBackfillGovernanceApprovalBoundary = {
        manualApprovalRequired: true,
        automaticPromotionAllowed: false,
        productionBackfillAllowed: false,
        corpusWriteAllowed: false,
        optimizerAllowed: false,
        allowedNextStep: 'MANUAL_REVIEW_ONLY',
    };

    const writePathPolicy: OutcomeBackfillGovernanceWritePathPolicy = {
        productionDbWriteAllowed: false,
        corpusJsonlWriteAllowed: false,
        predictionRowWriteAllowed: false,
        strategySignalWriteAllowed: false,
        artifactOnly: true,
    };

    const riskFlags: string[] = [];
    if (!corpusUnchanged) riskFlags.push('CORPUS_LINE_COUNT_CHANGED');
    if (input.currentQualityGate?.qualityStatus) {
        riskFlags.push(`CURRENT_QUALITY_STATUS_${input.currentQualityGate.qualityStatus}`);
    }
    if (input.qualityImpactPreview.projectedQualityStatus !== 'PASS_FOR_OBSERVABILITY_ONLY') {
        riskFlags.push(`PROJECTED_QUALITY_${input.qualityImpactPreview.projectedQualityStatus}`);
    }
    if (blockedToReadyCount > 0) {
        riskFlags.push('BLOCKED_TO_READY_TRANSITIONS_PRESENT');
    }
    riskFlags.push('PREVIEW_ONLY_IMPACT');
    riskFlags.push('MANUAL_REVIEW_REQUIRED');

    const requiredNextApprovals = [
        'CTO_MANUAL_REVIEW',
        'DATA_GOVERNANCE_REVIEW',
    ];

    const gate: OutcomeBackfillGovernanceGate = {
        governanceGateVersion: OUTCOME_BACKFILL_GOVERNANCE_GATE_VERSION,
        governanceRunId: options.governanceRunId,
        generatedAt: options.generatedAt,
        inputSummary: {
            candidateCount: input.candidateSelection.selectedCount,
            rehearsalItemCount: input.rehearsal.rehearsalItems.length,
            blockedToReadyCount,
            currentCorpusLineCount: input.currentCorpusLineCount,
            currentQualityStatus: input.currentQualityGate?.qualityStatus ?? null,
            projectedQualityStatus: input.qualityImpactPreview.projectedQualityStatus,
            projectedCoverageRatio: input.qualityImpactPreview.projectedCoverageRatio,
            previewOnly: true,
        },
        gateChecks,
        gateStatus,
        decision,
        approvalBoundary,
        writePathPolicy,
        riskFlags,
        requiredNextApprovals,
        validationStatus: 'PASS',
        validationMessages: [],
    };

    const validation = validateOutcomeBackfillGovernanceGate(gate);
    gate.validationStatus = validation.validationStatus;
    gate.validationMessages = validation.validationMessages;

    return gate;
}

export function validateOutcomeBackfillGovernanceGate(
    gate: OutcomeBackfillGovernanceGate,
): OutcomeBackfillGovernanceValidationResult {
    const messages: string[] = [];
    let status: 'PASS' | 'WARN' | 'FAIL' = 'PASS';

    const b = gate.approvalBoundary;
    if (!b.manualApprovalRequired) {
        messages.push('FAIL: manualApprovalRequired must be true');
        status = 'FAIL';
    }
    if (b.automaticPromotionAllowed !== false) {
        messages.push('FAIL: automaticPromotionAllowed must be false');
        status = 'FAIL';
    }
    if (b.productionBackfillAllowed !== false) {
        messages.push('FAIL: productionBackfillAllowed must be false');
        status = 'FAIL';
    }
    if (b.corpusWriteAllowed !== false) {
        messages.push('FAIL: corpusWriteAllowed must be false');
        status = 'FAIL';
    }
    if (b.optimizerAllowed !== false) {
        messages.push('FAIL: optimizerAllowed must be false');
        status = 'FAIL';
    }
    if (b.allowedNextStep !== 'MANUAL_REVIEW_ONLY') {
        messages.push('FAIL: allowedNextStep must be MANUAL_REVIEW_ONLY');
        status = 'FAIL';
    }

    const p = gate.writePathPolicy;
    if (p.productionDbWriteAllowed !== false) {
        messages.push('FAIL: productionDbWriteAllowed must be false');
        status = 'FAIL';
    }
    if (p.corpusJsonlWriteAllowed !== false) {
        messages.push('FAIL: corpusJsonlWriteAllowed must be false');
        status = 'FAIL';
    }
    if (p.predictionRowWriteAllowed !== false) {
        messages.push('FAIL: predictionRowWriteAllowed must be false');
        status = 'FAIL';
    }
    if (p.strategySignalWriteAllowed !== false) {
        messages.push('FAIL: strategySignalWriteAllowed must be false');
        status = 'FAIL';
    }
    if (p.artifactOnly !== true) {
        messages.push('FAIL: artifactOnly must be true');
        status = 'FAIL';
    }

    if (gate.gateStatus === 'BLOCKED' && gate.decision === 'ALLOW_MANUAL_REVIEW_ONLY') {
        messages.push('FAIL: BLOCKED gate cannot allow manual review only');
        status = 'FAIL';
    }

    if (gate.gateStatus === 'READY_FOR_MANUAL_REVIEW' && gate.decision !== 'ALLOW_MANUAL_REVIEW_ONLY') {
        messages.push('FAIL: ready gate must allow manual review only');
        status = 'FAIL';
    }

    if (gate.gateStatus === 'DATA_LIMITED' && gate.decision === 'ALLOW_MANUAL_REVIEW_ONLY') {
        messages.push('FAIL: data-limited gate must not auto-promote');
        status = 'FAIL';
    }

    if (hasForbiddenClaim(JSON.stringify(gate))) {
        messages.push('FAIL: forbidden claim detected in outcome backfill governance gate');
        status = 'FAIL';
    }

    if (status === 'PASS') {
        messages.push('PASS: outcome backfill governance gate safety contracts verified');
    }

    return { validationStatus: status, validationMessages: messages };
}

/**
 * P13-HARDRESET PART B: MonthlyRevenue PIT Contract Utility
 *
 * Defines deterministic rules for MonthlyRevenue PIT (Point-In-Time) gate.
 * Taiwan monthly revenue is released ~10th of the following month.
 *
 * SAFETY CONTRACT:
 * - Does NOT write production DB.
 * - Does NOT modify scoring formulas or bucket thresholds.
 * - Does NOT use stock price / returnPct / realizedReturnClass to infer releaseDate.
 * - Does NOT use outcomeDate / horizonDays to infer releaseDate.
 * - All inference is deterministic and documented.
 * - No ROI / win-rate / alpha / profit claims.
 */

// ── Types ────────────────────────────────────────────────────────────────────

