export type P23Classification =
  | 'P23_READY_TO_REQUEST_PRODUCTION_EXECUTION_APPROVAL'
  | 'P23_REQUIRES_BACKUP_RESTORE_HARDENING'
  | 'P23_REQUIRES_ROLLBACK_HARDENING'
  | 'P23_REQUIRES_MONITORING_HARDENING'
  | 'P23_REQUIRES_RUNBOOK_HARDENING'
  | 'P23_IMPLEMENTATION_REVIEW_REJECTED'
  | 'P23_IMPLEMENTATION_REVIEW_BLOCKED_BY_ARTIFACTS';

export interface ImplementationReadinessDecision {
  phase: string;
  generatedAt: string;
  classification: P23Classification;
  readyToRequestExecutionApproval: boolean;
  approvalGranted: false;
  productionMigrationApplied: false;
  recommendedExecutionToken: string;
  evaluations: Record<string, 'PASS' | 'FAIL'>;
  blockers: string[];
  whyNotApproved: string;
}

export function buildImplementationReadinessDecision(inputs: {
  backupRestoreComplete: boolean;
  runbookComplete: boolean;
  rollbackComplete: boolean;
  monitoringComplete: boolean;
  allCommandsPlaceholder: boolean;
  artifactsComplete?: boolean;
}): ImplementationReadinessDecision {
  const now = new Date().toISOString();
  const blockers: string[] = [];

  const evaluations: Record<string, 'PASS' | 'FAIL'> = {
    backupRestoreComplete: inputs.backupRestoreComplete ? 'PASS' : 'FAIL',
    runbookComplete: inputs.runbookComplete ? 'PASS' : 'FAIL',
    rollbackComplete: inputs.rollbackComplete ? 'PASS' : 'FAIL',
    monitoringComplete: inputs.monitoringComplete ? 'PASS' : 'FAIL',
    allCommandsPlaceholder: inputs.allCommandsPlaceholder ? 'PASS' : 'FAIL',
    artifactsComplete: inputs.artifactsComplete !== false ? 'PASS' : 'FAIL',
    approvalGuard: 'PASS', // approvalGranted=false — always PASS in P23
    migrationGuard: 'PASS', // productionMigrationApplied=false — always PASS in P23
  };

  if (inputs.artifactsComplete === false) blockers.push('required artifacts missing');
  if (!inputs.backupRestoreComplete) blockers.push('backup/restore plan incomplete');
  if (!inputs.runbookComplete) blockers.push('migration runbook incomplete');
  if (!inputs.rollbackComplete) blockers.push('rollback package incomplete');
  if (!inputs.monitoringComplete) blockers.push('monitoring checklist incomplete');
  if (!inputs.allCommandsPlaceholder) blockers.push('non-placeholder production commands detected');

  let classification: P23Classification;
  if (inputs.artifactsComplete === false) {
    classification = 'P23_IMPLEMENTATION_REVIEW_BLOCKED_BY_ARTIFACTS';
  } else if (!inputs.backupRestoreComplete) {
    classification = 'P23_REQUIRES_BACKUP_RESTORE_HARDENING';
  } else if (!inputs.rollbackComplete) {
    classification = 'P23_REQUIRES_ROLLBACK_HARDENING';
  } else if (!inputs.monitoringComplete) {
    classification = 'P23_REQUIRES_MONITORING_HARDENING';
  } else if (!inputs.runbookComplete) {
    classification = 'P23_REQUIRES_RUNBOOK_HARDENING';
  } else if (!inputs.allCommandsPlaceholder) {
    classification = 'P23_IMPLEMENTATION_REVIEW_REJECTED';
  } else {
    classification = 'P23_READY_TO_REQUEST_PRODUCTION_EXECUTION_APPROVAL';
  }

  const readyToRequestExecutionApproval =
    classification === 'P23_READY_TO_REQUEST_PRODUCTION_EXECUTION_APPROVAL';

  return {
    phase: 'P23',
    generatedAt: now,
    classification,
    readyToRequestExecutionApproval,
    approvalGranted: false,
    productionMigrationApplied: false,
    recommendedExecutionToken: SUGGESTED_P24_EXECUTION_TOKEN,
    evaluations,
    blockers,
    whyNotApproved:
      'P23 reviews implementation readiness only. ' +
      'Production execution approval requires an explicit P24 execution token: ' +
      SUGGESTED_P24_EXECUTION_TOKEN + '. ' +
      'That token has not been provided. CTO/CEO must grant it in P24.',
  };
}

/**
 * P26ACorpusReasonRenderer.ts
 * P26A-RENDERER-FIX-HARDRESET
 *
 * Read-time renderer for ActiveScoringSnapshot reason text.
 *
 * Problem addressed:
 *   The P3/P19 frozen corpus was built before enrichReasonFromExistingFactors was added
 *   to ActiveScoringSnapshotBuilder. As a result, 9 SCORING_UNDEROUTPUT cases in the
 *   corpus have reasonSnapshot = single generic token (e.g. "技術偏多") even though
 *   factorSnapshot contains 10+ rich signals.
 *
 * Solution:
 *   At READ time (walkthrough / API display / audit), apply enrichment if reasonSnapshot
 *   is a single generic token and factorSnapshot is non-empty.
 *   This does NOT modify the corpus files. This does NOT change alphaScore or researchBucket.
 *
 * Guarantees:
 *   - Pure function — same input → same output (deterministic)
 *   - No DB write
 *   - No corpus mutation
 *   - No external API / LLM call
 *   - No alphaScore change
 *   - No recommendationBucket / researchBucket change
 *   - No new factors introduced (reads only from factorSnapshot)
 *   - No buy/sell claims. No performance or return claims.
 *
 * Not investment advice. Not a trading system.
 */

import { enrichReasonFromExistingFactors } from './P26AReasonFactorEnrichmentUtils';
import type { ActiveScoringSnapshot } from './ActiveScoringSnapshotBuilder';

// ─── Renderer version ────────────────────────────────────────────────────────

// P28C-RENDERER-REPAIR: bumped from v1 to v2 (scoreSnapshot pass-through + mixed-signal template)
export const CORPUS_REASON_RENDERER_VERSION = 'p26a-corpus-renderer-v2';

// ─── P28C: Mixed-signal detection ──────────────────────────────────────────

/**
 * detectMixedSignal
 *
 * P28C-RENDERER-REPAIR: Detects when MA trend and MACD point in opposite directions.
 * Returns true when MA 空頭排列 + MACD 多方動能, or MA 多頭排列 + MACD 空方動能.
 * Pure function — no side effects.
 */
export function detectMixedSignal(factors: string[]): boolean {
    const maTrend = factors.find(f => f.startsWith('MA 趨勢')) ?? '';
    const macd = factors.find(f => f.startsWith('MACD')) ?? '';

    const maBearish = maTrend.includes('空頭排列') || maTrend.includes('空方');
    const maBullish = maTrend.includes('多頭排列') || maTrend.includes('多方');
    const macdBullish = macd.includes('MACD > 0') || macd.includes('多方動能');
    const macdBearish = macd.includes('MACD < 0') || macd.includes('空方動能');

    return (maBearish && macdBullish) || (maBullish && macdBearish);
}

/**
 * buildMixedSignalNote
 *
 * Returns a neutral annotation noting that MA and MACD signals are contradictory.
 * Observational note — no trading signal implied. No buy/sell recommendation.
 */
export function buildMixedSignalNote(factors: string[]): string {
    const maTrend = factors.find(f => f.startsWith('MA 趨勢')) ?? '';
    const macd = factors.find(f => f.startsWith('MACD')) ?? '';
    if (!maTrend && !macd) return '';
    return `混合信號：MA 趨勢（${maTrend.split(':')[1]?.trim() ?? ''}）與 MACD（${macd.split(':')[1]?.trim() ?? ''}）方向分歧，技術信號需審慎解讀`;
}

// ─── Single-token detection ───────────────────────────────────────────────────

/**
 * SINGLE_TOKEN_GENERIC_REASONS
 *
 * Exhaustive set of collapsed single-token reason strings produced by
 * RuleBasedStockAnalyzer before P26A enrichment was added.
 * These are the patterns that indicate SNAPSHOT_FIELD_PRESENT_BUT_REASON_NOT_RENDERED.
 */
export const SINGLE_TOKEN_GENERIC_REASONS: ReadonlySet<string> = new Set([
    '技術偏多',
    '技術偏空',
    '法人買超',
    '法人賣超',
    '動能轉強',
    '動能走弱',
    '營收成長',
    '營收衰退',
    '資料觀察中',
    'technicalBullish',
    'technicalBearish',
    'chipBullish',
    'chipBearish',
    'momentumUp',
    'momentumDown',
    'revenueBullish',
    'revenueBearish',
]);

// ─── Types ────────────────────────────────────────────────────────────────────

export type RendererOutcome =
    | 'ENRICHED'           // single-token replaced with factorSnapshot-derived multi-factor text
    | 'ALREADY_RICH'       // reasonSnapshot already has multi-factor content, not replaced
    | 'FALLBACK_EMPTY'     // factorSnapshot empty — kept original reasonSnapshot
    | 'FALLBACK_NO_SNAPSHOT'; // no snapshot at all

export interface RenderedReason {
    renderedText: string;
    outcome: RendererOutcome;
    oldText: string;
    factorCount: number;
    rendererVersion: string;
    alphaScoreUnchanged: boolean;   // always true — renderer never touches alphaScore
    bucketUnchanged: boolean;       // always true — renderer never touches researchBucket
}

// ─── Core renderer ────────────────────────────────────────────────────────────

/**
 * isSingleTokenGenericReason
 *
 * Returns true if reasonText is a known single-token generic reason that
 * should be enriched with factorSnapshot content.
 */
export function isSingleTokenGenericReason(reasonText: string | null | undefined): boolean {
    if (!reasonText) return false;
    return SINGLE_TOKEN_GENERIC_REASONS.has(reasonText.trim());
}

/**
 * renderReasonFromCorpusSnapshot
 *
 * PURE FUNCTION — same input always produces same output.
 *
 * Takes a corpus snapshot (ActiveScoringSnapshot shape, as stored in JSONL corpus)
 * and returns an enriched reason text for display.
 *
 * If reasonSnapshot is a single generic token and factorSnapshot is non-empty:
 *   → applies enrichReasonFromExistingFactors → outcome = ENRICHED
 * If reasonSnapshot already has multi-factor content:
 *   → returns as-is → outcome = ALREADY_RICH
 * If factorSnapshot is empty:
 *   → returns original reasonSnapshot → outcome = FALLBACK_EMPTY
 *
 * NEVER modifies the input snapshot.
 * NEVER changes alphaScore or researchBucket.
 */
export function renderReasonFromCorpusSnapshot(snapshot: ActiveScoringSnapshot): RenderedReason {
    const oldText = snapshot.reasonSnapshot ?? '';
    const factorCount = snapshot.factorSnapshot?.length ?? 0;

    // Cannot enrich if no factors available
    if (factorCount === 0) {
        return {
            renderedText: oldText,
            outcome: 'FALLBACK_EMPTY',
            oldText,
            factorCount: 0,
            rendererVersion: CORPUS_REASON_RENDERER_VERSION,
            alphaScoreUnchanged: true,
            bucketUnchanged: true,
        };
    }

    // Already rich — has multi-factor content (contains '/' separator or multiple Chinese characters
    // with numerical evidence)
    if (!isSingleTokenGenericReason(oldText) && oldText.length > 20) {
        return {
            renderedText: oldText,
            outcome: 'ALREADY_RICH',
            oldText,
            factorCount,
            rendererVersion: CORPUS_REASON_RENDERER_VERSION,
            alphaScoreUnchanged: true,
            bucketUnchanged: true,
        };
    }

    // Single token or short generic reason → enrich from factorSnapshot
    const enriched = enrichReasonFromExistingFactors(snapshot);

    // P28C-RENDERER-REPAIR TR-03: append mixed-signal note if MA/MACD contradict
    const factors = snapshot.factorSnapshot ?? [];
    const mixedSignal = detectMixedSignal(factors);
    const mixedNote = mixedSignal ? ' / ' + buildMixedSignalNote(factors) : '';
    const renderedText = enriched + mixedNote;

    return {
        renderedText,
        outcome: 'ENRICHED',
        oldText,
        factorCount,
        rendererVersion: CORPUS_REASON_RENDERER_VERSION,
        alphaScoreUnchanged: true,
        bucketUnchanged: true,
    };
}

/**
 * renderReasonBatch
 *
 * Applies renderReasonFromCorpusSnapshot to multiple snapshots.
 * Pure — does not mutate inputs.
 */
export function renderReasonBatch(
    snapshots: ActiveScoringSnapshot[],
): RenderedReason[] {
    return snapshots.map(renderReasonFromCorpusSnapshot);
}

