  for (const r of results) {
    if (r.outcomeFieldsDetected) {
      violations.push(`${r.sourceCategory}: outcomeFieldsDetected=true — forbidden`);
    }
  }
  return { valid: violations.length === 0, violations };
}

export function validateSourceMappingReadOnly(
  results: SourceScanResult[]
): { valid: boolean; violations: string[] } {
  const violations: string[] = [];
  for (const r of results) {
    if (!r.readOnly) {
      violations.push(`${r.sourceCategory}: readOnly=false — must be true`);
    }
  }
  return { valid: violations.length === 0, violations };
}

// P26F3-2-HARDRESET: Manual MonthlyRevenue Source Scanner
// DISCLAIMER: Does not constitute investment advice.
// READ-ONLY. No DB write. No corpus write. No external API. No Math.random.

import { P26F3_2_ACCEPTED_FORMATS, P26F3_2_FORBIDDEN_FIELDS, P26F3_2_CLASSIFICATIONS } from "./P26F32ManualSourceAcquisitionContractUtils";

const fs = require("fs") as typeof import("fs");
const path = require("path") as typeof import("path");

export type ManualSourceFormat = "csv" | "json" | "jsonl" | "unknown";

export interface ManualSourceFileScanResult {
  fileName: string;
  filePath: string;
  format: ManualSourceFormat;
  parseStatus: "ok" | "error" | "empty" | "unknown_format";
  rowCount: number;
  forbiddenFieldsFound: string[];
  hasForbiddenFields: boolean;
  parseError?: string;
  rows: Record<string, unknown>[];
}

export interface ManualSourceDropzoneScanSummary {
  dropzonePath: string;
  scannedAt: string;
  totalFiles: number;
  parsedFiles: number;
  errorFiles: number;
  totalRows: number;
  forbiddenFieldFiles: number;
  unknownFormatFiles: number;
  classification: string;
  fileResults: ManualSourceFileScanResult[];
  readOnly: true;
  dbWriteAllowed: false;
  corpusWriteAllowed: false;
}

export function detectManualSourceFormat(filePath: string): ManualSourceFormat {
  const ext = path.extname(filePath).toLowerCase().replace(".", "");
  if (ext === "csv") return "csv";
  if (ext === "json") return "json";
  if (ext === "jsonl" || ext === "ndjson") return "jsonl";
  return "unknown";
}

function parseCSV(content: string): Record<string, unknown>[] {
  const lines = content.split(/\r?\n/).filter(l => l.trim());
  if (lines.length < 2) return [];
  const headers = lines[0].split(",").map(h => h.trim().replace(/^"|"$/g, ""));
  const rows: Record<string, unknown>[] = [];
  for (let i = 1; i < lines.length; i++) {
    const vals = lines[i].split(",").map(v => v.trim().replace(/^"|"$/g, ""));
    if (vals.length !== headers.length) continue;
    const row: Record<string, unknown> = {};
    for (let j = 0; j < headers.length; j++) {
      row[headers[j]] = vals[j];
    }
    rows.push(row);
  }
  return rows;
}

function parseJSONL(content: string): Record<string, unknown>[] {
  return content.split("\n").filter(l => l.trim()).map(l => JSON.parse(l));
}

export function parseManualSourceFile(filePath: string): { rows: Record<string, unknown>[]; error?: string } {
  try {
    const content = fs.readFileSync(filePath, "utf8");
    const fmt = detectManualSourceFormat(filePath);
    if (fmt === "csv") return { rows: parseCSV(content) };
    if (fmt === "json") {
      const parsed = JSON.parse(content);
      return { rows: Array.isArray(parsed) ? parsed : [parsed] };
    }
    if (fmt === "jsonl") return { rows: parseJSONL(content) };
    return { rows: [], error: "unknown_format" };
  } catch (e: unknown) {
    return { rows: [], error: e instanceof Error ? e.message : String(e) };
  }
}

export function classifyManualSourceFile(filePath: string): ManualSourceFileScanResult {
  const fileName = path.basename(filePath);
  const format = detectManualSourceFormat(filePath);
  if (format === "unknown") {
    return {
      fileName, filePath, format,
      parseStatus: "unknown_format", rowCount: 0,
      forbiddenFieldsFound: [], hasForbiddenFields: false, rows: [],
    };
  }
  const { rows, error } = parseManualSourceFile(filePath);
  const forbidden = Array.from(new Set(rows.flatMap(r => P26F3_2_FORBIDDEN_FIELDS.filter(f => f in r && r[f] != null))));
  return {
    fileName, filePath, format,
    parseStatus: error ? "error" : rows.length === 0 ? "empty" : "ok",
    rowCount: rows.length,
    forbiddenFieldsFound: forbidden,
    hasForbiddenFields: forbidden.length > 0,
    parseError: error,
    rows,
  };
}

export function scanManualMonthlyRevenueDropzone(dropzonePath: string): ManualSourceDropzoneScanSummary {
  const scannedAt = new Date().toISOString();
  if (!fs.existsSync(dropzonePath)) {
    return {
      dropzonePath, scannedAt, totalFiles: 0, parsedFiles: 0, errorFiles: 0,
      totalRows: 0, forbiddenFieldFiles: 0, unknownFormatFiles: 0,
      classification: P26F3_2_CLASSIFICATIONS.SOURCE_NOT_PROVIDED_PACKAGE_READY,
      fileResults: [], readOnly: true, dbWriteAllowed: false, corpusWriteAllowed: false,
    };
  }
  const allFiles = fs.readdirSync(dropzonePath).filter((f: string) => {
    if (f.startsWith(".")) return false;
    if (f === "README.md" || f === "EXPECTED_SCHEMA.json") return false;
    return [".csv",".json",".jsonl",".ndjson"].includes(path.extname(f).toLowerCase());
  });
  if (allFiles.length === 0) {
    return {
      dropzonePath, scannedAt, totalFiles: 0, parsedFiles: 0, errorFiles: 0,
      totalRows: 0, forbiddenFieldFiles: 0, unknownFormatFiles: 0,
      classification: P26F3_2_CLASSIFICATIONS.SOURCE_NOT_PROVIDED_PACKAGE_READY,
      fileResults: [], readOnly: true, dbWriteAllowed: false, corpusWriteAllowed: false,
    };
  }
  const fileResults = allFiles.map((f: string) => classifyManualSourceFile(path.join(dropzonePath, f)));
  const parsedFiles = fileResults.filter(r => r.parseStatus === "ok").length;
  const errorFiles = fileResults.filter(r => r.parseStatus === "error").length;
  const totalRows = fileResults.reduce((s, r) => s + r.rowCount, 0);
  const forbiddenFieldFiles = fileResults.filter(r => r.hasForbiddenFields).length;
  const unknownFormatFiles = fileResults.filter(r => r.format === "unknown").length;
  let classification = P26F3_2_CLASSIFICATIONS.MANUAL_SOURCE_ACCEPTED_DRY_RUN;
  if (forbiddenFieldFiles > 0 || errorFiles > 0 || unknownFormatFiles > 0) {
    classification = P26F3_2_CLASSIFICATIONS.SOURCE_FILES_REJECTED;
  }
  return {
    dropzonePath, scannedAt, totalFiles: allFiles.length, parsedFiles, errorFiles,
    totalRows, forbiddenFieldFiles, unknownFormatFiles, classification,
    fileResults, readOnly: true, dbWriteAllowed: false, corpusWriteAllowed: false,
  };
}

export function summarizeManualSourceScan(scanResults: ManualSourceDropzoneScanSummary): string {
  const lines = [
    `# P26F3-2 Manual Source Scan`,
    `Scanned at: ${scanResults.scannedAt}`,
    `Total files: ${scanResults.totalFiles}`,
    `Parsed OK: ${scanResults.parsedFiles}`,
    `Errors: ${scanResults.errorFiles}`,
    `Total rows: ${scanResults.totalRows}`,
    `Forbidden field files: ${scanResults.forbiddenFieldFiles}`,
    `Unknown format files: ${scanResults.unknownFormatFiles}`,
    `Classification: ${scanResults.classification}`,
  ];
  return lines.join("\n");
}

export function validateManualSourceNoOutcomeFields(scanResults: ManualSourceDropzoneScanSummary): { pass: boolean; violatingFiles: string[] } {
  const violatingFiles = scanResults.fileResults.filter(r => r.hasForbiddenFields).map(r => r.fileName);
  return { pass: violatingFiles.length === 0, violatingFiles };
}

export function validateManualSourceReadOnly(scanResults: ManualSourceDropzoneScanSummary): { pass: boolean; dbWriteAttempted: boolean; corpusWriteAttempted: boolean } {
  return {
    pass: scanResults.dbWriteAllowed === false && scanResults.corpusWriteAllowed === false,
    dbWriteAttempted: false,
    corpusWriteAttempted: false,
  };
}

// P26F3-3-HARDRESET: Drop-zone Inventory Utils
// DISCLAIMER: Does not constitute investment advice.
// READ-ONLY. No DB write. No corpus write. No external API. No Math.random.

const fs = require("fs") as typeof import("fs");
const path = require("path") as typeof import("path");
const crypto = require("crypto") as typeof import("crypto");

export type InventoryClassification = "SOURCE_FILES_PRESENT" | "SOURCE_NOT_PROVIDED" | "UNSUPPORTED_FILES_ONLY";

export interface DropzoneFileEntry {
  fileName: string;
  filePath: string;
  format: string;
  isCandidate: boolean;
  isIgnored: boolean;
  fileSizeBytes: number;
  sha256: string;
  mtimeMs: number;
  mtimeISO: string;
  suspectedPeriod: string | null;
}

export interface DropzoneInventory {
  dropzonePath: string;
  inventoriedAt: string;
  totalFiles: number;
  candidateSourceFiles: number;
  ignoredFiles: number;
  unsupportedFiles: number;
  supportedFormatCounts: { csv: number; json: number; jsonl: number };
  classification: InventoryClassification;
  files: DropzoneFileEntry[];
  readOnly: true;
  dbWriteAllowed: false;
  corpusWriteAllowed: false;
}

const IGNORED_NAMES = ["README.md", "EXPECTED_SCHEMA.json", "EXPECTED_FILENAMES.md", ".gitkeep", ".gitignore", ".DS_Store"];
const CANDIDATE_EXTS = [".csv", ".json", ".jsonl", ".ndjson"];

function detectFormat(fileName: string): string {
  const ext = path.extname(fileName).toLowerCase();
  if (ext === ".csv") return "csv";
  if (ext === ".json") return "json";
  if (ext === ".jsonl" || ext === ".ndjson") return "jsonl";
  return "unknown";
}

function sha256File(filePath: string): string {
  return crypto.createHash("sha256").update(fs.readFileSync(filePath)).digest("hex");
}

function suspectPeriodFromFilename(fileName: string): string | null {
  const m = fileName.match(/(\d{4})[_\-]?(0[1-9]|1[0-2])/);
  if (m) return `${m[1]}-${m[2]}`;
  return null;
}

export function inventoryDropzone(dropzonePath: string): DropzoneInventory {
  const inventoriedAt = new Date().toISOString();
  const result: DropzoneInventory = {
    dropzonePath,
    inventoriedAt,
    totalFiles: 0,
    candidateSourceFiles: 0,
    ignoredFiles: 0,
    unsupportedFiles: 0,
    supportedFormatCounts: { csv: 0, json: 0, jsonl: 0 },
    classification: "SOURCE_NOT_PROVIDED",
    files: [],
    readOnly: true,
    dbWriteAllowed: false,
    corpusWriteAllowed: false,
  };

  if (!fs.existsSync(dropzonePath)) return result;

  const allNames = fs.readdirSync(dropzonePath);
  result.totalFiles = allNames.length;

  for (const name of allNames) {
    const fp = path.join(dropzonePath, name);
    let stat: ReturnType<typeof fs.statSync>;
    try { stat = fs.statSync(fp); } catch { continue; }
    const ignored = name.startsWith(".") || IGNORED_NAMES.includes(name) || /DO_NOT_IMPORT|TEMPLATE/i.test(name);
    const ext = path.extname(name).toLowerCase();
    const isCandidate = !ignored && CANDIDATE_EXTS.includes(ext);
    const format = detectFormat(name);
    let fileSha = "";
    try { fileSha = sha256File(fp); } catch { fileSha = "UNREADABLE"; }
    const entry: DropzoneFileEntry = {
      fileName: name,
      filePath: fp,
      format,
      isCandidate,
      isIgnored: ignored,
      fileSizeBytes: stat.size,
      sha256: fileSha,
      mtimeMs: stat.mtimeMs,
      mtimeISO: new Date(stat.mtimeMs).toISOString(),
      suspectedPeriod: suspectPeriodFromFilename(name),
    };
    result.files.push(entry);
    if (ignored) {
      result.ignoredFiles++;
    } else if (isCandidate) {
      result.candidateSourceFiles++;
      if (format === "csv") result.supportedFormatCounts.csv++;
      else if (format === "json") result.supportedFormatCounts.json++;
      else if (format === "jsonl") result.supportedFormatCounts.jsonl++;
    } else {
      result.unsupportedFiles++;
    }
  }

  if (result.candidateSourceFiles > 0) {
    result.classification = "SOURCE_FILES_PRESENT";
  } else if (result.unsupportedFiles > 0) {
    result.classification = "UNSUPPORTED_FILES_ONLY";
  } else {
    result.classification = "SOURCE_NOT_PROVIDED";
  }

  return result;
}

export function summarizeInventory(inv: DropzoneInventory): string {
  const lines = [
    `# P26F3-3 Drop-zone Inventory`,
    `Inventoried: ${inv.inventoriedAt}`,
    `Total files: ${inv.totalFiles}`,
    `Candidate source files: ${inv.candidateSourceFiles}`,
    `Ignored files: ${inv.ignoredFiles}`,
    `Unsupported files: ${inv.unsupportedFiles}`,
    `Format counts: CSV=${inv.supportedFormatCounts.csv} JSON=${inv.supportedFormatCounts.json} JSONL=${inv.supportedFormatCounts.jsonl}`,
    `Classification: ${inv.classification}`,
  ];
  return lines.join("\n");
}

// P26F3-HARDRESET: MonthlyRevenue Historical Source Scanner Utils
// DISCLAIMER: Does not constitute investment advice. Read-only filesystem scan.
// No DB write. No corpus overwrite. No scoring formula change. Dry-run only.

export interface HistoricalSourceScanResult {
  scannedPaths: string[];
  totalFilesScanned: number;
  localSourcesFound: number;
  realSourceCandidates: SourceCandidate[];
  templateOnlyCandidates: SourceCandidate[];
  missingPeriods: string[];
  missingSymbols: string[];
  scanClassification: string;
}

export interface SourceCandidate {
  path: string;
  sourceType: "REAL_SOURCE" | "TEMPLATE_ONLY" | "FIXTURE" | "GENERATED_ARTIFACT" | "UNKNOWN";
  periods: string[];
  symbols: string[];
  hasRevenue: boolean;
  hasReleaseDate: boolean;
  rowCount: number;
  note: string;
}

const TARGET_PERIODS = ["2025-09","2025-10","2025-11","2025-12","2026-01"];
const TARGET_SYMBOLS = ["0055","00712","00738U","00830","00891","00903","1210","1308","1314","1319","1326","1402","1434","1513","1536","1560","1598","1605","1710","1717","1802","2317","2330","2454","6415"];
const SCAN_DIRS = ["data","prisma","scripts","outputs","fixtures","seed"];
const REVENUE_KEYWORDS = /revenue|monthly|twse|月營收|營收/i;
const OUTCOME_FIELDS = ["outcomePrice","returnPct","realizedReturnClass"];

export function scanLocalMonthlyRevenueHistoricalSources(workspaceRoot: string): HistoricalSourceScanResult {
  const fs = require("fs") as typeof import("fs");
  const path = require("path") as typeof import("path");
  const scannedPaths: string[] = [];
  const realSourceCandidates: SourceCandidate[] = [];
  const templateOnlyCandidates: SourceCandidate[] = [];
  let totalFilesScanned = 0;

  function scanDir(dir: string): void {
    const fullDir = path.join(workspaceRoot, dir);
    if (!fs.existsSync(fullDir)) return;
    scannedPaths.push(dir);
    const entries = fs.readdirSync(fullDir, { withFileTypes: true });
    for (const entry of entries) {
      if (entry.isDirectory()) {
        // only recurse one level for safety
        continue;
      }
      const ext = path.extname(entry.name).toLowerCase();
      if (![".csv",".json",".jsonl",".txt"].includes(ext)) continue;
      const fullPath = path.join(fullDir, entry.name);
      const relPath = path.join(dir, entry.name);
      totalFilesScanned++;
      try {
        const content = fs.readFileSync(fullPath, "utf8");
        if (!REVENUE_KEYWORDS.test(entry.name) && !REVENUE_KEYWORDS.test(content.slice(0, 500))) continue;
        const candidate = classifyHistoricalSourceCandidate(relPath, content);
        if (candidate.sourceType === "REAL_SOURCE") {
          realSourceCandidates.push(candidate);
        } else {
          templateOnlyCandidates.push(candidate);
        }
      } catch {
        // skip unreadable files
      }
    }
  }

  for (const dir of SCAN_DIRS) {
    scanDir(dir);
  }

  const coveredPeriods = new Set<string>();
  const coveredSymbols = new Set<string>();
  for (const c of realSourceCandidates) {
    c.periods.forEach(p => coveredPeriods.add(p));
    c.symbols.forEach(s => coveredSymbols.add(s));
  }

  const missingPeriods = TARGET_PERIODS.filter(p => !coveredPeriods.has(p));
  const missingSymbols = TARGET_SYMBOLS.filter(s => !coveredSymbols.has(s));

  const scanClassification = realSourceCandidates.length === 0
    ? "NO_LOCAL_HISTORICAL_SOURCE_FOUND"
    : "LOCAL_HISTORICAL_SOURCE_FOUND";

  return {
    scannedPaths,
    totalFilesScanned,
    localSourcesFound: realSourceCandidates.length,
    realSourceCandidates,
    templateOnlyCandidates,
    missingPeriods,
    missingSymbols,
    scanClassification,
  };
}

export function classifyHistoricalSourceCandidate(filePath: string, content: string): SourceCandidate {
  const fp = filePath.toLowerCase();
  let sourceType: SourceCandidate["sourceType"] = "UNKNOWN";

  if (fp.includes("p26f") || fp.includes("p26e") || fp.includes("online_validation")) {
    sourceType = "GENERATED_ARTIFACT";
  } else if (fp.includes("fixture") || fp.includes("seed") || fp.includes("mock")) {
    sourceType = "FIXTURE";
  } else if (fp.includes("template")) {
    sourceType = "TEMPLATE_ONLY";
  } else if (fp.includes("data/") || fp.endsWith(".csv")) {
    sourceType = "REAL_SOURCE";
  }

  const hasRevenue = /revenue/i.test(content);
  const hasReleaseDate = /releaseDate/i.test(content);

  const periods: string[] = [];
  for (const p of TARGET_PERIODS) {
    const [y, m] = p.split("-");
    if (content.includes(`"year":${y}`) && content.includes(`"month":${parseInt(m, 10)}`)) {
      periods.push(p);
    }
  }

  const symbols: string[] = [];
  for (const sym of TARGET_SYMBOLS) {
    if (content.includes(`"${sym}"`) || content.includes(`,"${sym}",`)) {
      symbols.push(sym);
    }
  }

  let rowCount = 0;
  try {
    if (filePath.endsWith(".jsonl")) {
      rowCount = content.split("\n").filter(l => l.trim()).length;
    } else if (filePath.endsWith(".json")) {
      const parsed = JSON.parse(content);
      rowCount = Array.isArray(parsed) ? parsed.length : 1;
    }
  } catch {
    rowCount = 0;
  }

  return {
    path: filePath,
    sourceType,
    periods,
    symbols,
    hasRevenue,
    hasReleaseDate,
    rowCount,
    note: sourceType === "GENERATED_ARTIFACT"
      ? "P26F generated artifact — not a real historical source"
      : sourceType === "FIXTURE"
      ? "Fixture/seed file — not a verified official source"
      : "Classified by path/content heuristic",
  };
}

export function extractHistoricalSourceMetadata(source: SourceCandidate): object {
  return {
    path: source.path,
    sourceType: source.sourceType,
    periodCount: source.periods.length,
    symbolCount: source.symbols.length,
    hasRevenue: source.hasRevenue,
    hasReleaseDate: source.hasReleaseDate,
    rowCount: source.rowCount,
    note: source.note,
  };
}

export function summarizeHistoricalSourceAvailability(scanResults: HistoricalSourceScanResult): object {
  return {
    scannedPaths: scanResults.scannedPaths,
    totalFilesScanned: scanResults.totalFilesScanned,
    localSourcesFound: scanResults.localSourcesFound,
    realSourceCount: scanResults.realSourceCandidates.length,
    templateOnlyCount: scanResults.templateOnlyCandidates.length,
    missingPeriods: scanResults.missingPeriods,
    missingSymbols: scanResults.missingSymbols,
    scanClassification: scanResults.scanClassification,
    allTargetPeriodsPresent: scanResults.missingPeriods.length === 0,
    allTargetSymbolsPresent: scanResults.missingSymbols.length === 0,
  };
}

export function validateHistoricalSourceNoOutcomeFields(scanResults: HistoricalSourceScanResult): { valid: boolean; violations: string[] } {
  const violations: string[] = [];
  for (const c of [...scanResults.realSourceCandidates, ...scanResults.templateOnlyCandidates]) {
    for (const field of OUTCOME_FIELDS) {
      if (c.note.toLowerCase().includes(field.toLowerCase())) {
        violations.push(`Source ${c.path} references outcome field: ${field}`);
      }
    }
  }
  return { valid: violations.length === 0, violations };
}

export function validateHistoricalSourceReadOnly(scanResults: HistoricalSourceScanResult): { valid: boolean; violations: string[] } {
  // Scan is always read-only — just verify no write markers
  const violations: string[] = [];
  if ((scanResults as Record<string, unknown>)["dbWritePerformed"]) {
    violations.push("Unexpected dbWritePerformed flag detected");
  }
  return { valid: violations.length === 0, violations };
}

/**
 * P28A Scoring Underoutput Audit Utilities
 *
 * Read-only audit framework for P26A's 9 deferred SCORING_UNDEROUTPUT cases.
 * Extracts, enriches, and classifies cases without modifying scores or templates.
 */

import fs from 'fs';
import path from 'path';

/**
 * Underoutput Classification Categories
 */
export enum UnderoutputClassification {
  NO_TRIGGERED_FACTOR = 'NO_TRIGGERED_FACTOR',
  CONTRIBUTION_BELOW_REASON_THRESHOLD = 'CONTRIBUTION_BELOW_REASON_THRESHOLD',
  TEMPLATE_BRANCH_MISSING = 'TEMPLATE_BRANCH_MISSING',
  UNKNOWN_NEEDS_CODE_TRACE = 'UNKNOWN_NEEDS_CODE_TRACE'
}

/**
 * P26A Underoutput Case structure from p26a_scoring_underoutput_9case_audit.json
 */
export interface P26AUnderoutputCase {
  caseId: string;
  symbol: string;
  asOfDate: string;
  horizon: number;
  bucket: string;
  alphaScore: number;
  reasonRaw: string;
