      const lines = content.split('\n');
      for (const line of lines) {
        if (ALLOWED_CLAIMS.test(line)) continue;
        const match = FORBIDDEN_CLAIMS.exec(line);
        if (match) {
          throw new Error(`Forbidden claim "${match[0]}" in ${f}: "${line.trim()}"`);
        }
      }
    }
  });
});

